function requestStops(){stashDay();return [...new Set(state.days.flatMap(d=>d.ids))].filter(id=>place(id));}
function home(){const resume=isGuest()?null:activeMateStep()||(state.saved?{route:'planner',label:'Continue planning'}:null);return `<section class="import-card action-import"><div class="import-heading"><span class="import-icon">${icon('link')}</span><div><h1>Start with a link</h1><p class="import-subtext">Save places from your favorite Shorts and Reels, then plan your trip.</p></div></div><form id="extract-form"><label class="sr-only" for="video-url">YouTube Shorts or Instagram Reels link</label><input id="video-url" type="url" inputmode="url" autocomplete="off" autocapitalize="none" spellcheck="false" aria-describedby="url-error" placeholder="Paste a video link" maxlength="2048"><button class="btn" type="submit">Find places <span aria-hidden="true">→</span></button><p id="url-error" class="error" role="alert"></p></form></section>${resume?`<a class="resume-action" href="#${resume.route}"><div><span>Pick up where you left off</span><strong>${resume.label}</strong></div><span aria-hidden="true">→</span></a>`:''}${discoveryPlaces()}`;}
function processing(){const fail=state.extraction==='failed';return `<section class="centerbox card pad extraction-card ${fail?'is-failed':''}" aria-labelledby="extraction-title"><div class="extraction-visual" aria-hidden="true"><svg viewBox="0 0 48 48" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round">${fail?'<rect x="9" y="7" width="30" height="34" rx="9"/><path d="M24 16v10m0 6h.01"/>':'<path d="M33 20c0 8-9 15-9 15s-9-7-9-15a9 9 0 1 1 18 0Z"/><circle cx="24" cy="20" r="3"/><path d="M13 32H9l-4 9h38l-4-9h-4"/>'}</svg></div><div class="eyebrow">Find places in a video</div><h1 id="extraction-title">${fail?'We could not open this video.':'Looking for the places in your video…'}</h1>${fail?'':`<div class="extraction-progress" aria-hidden="true"><span></span></div><ol class="extraction-stages"><li class="is-complete"><span class="extraction-stage-icon" aria-hidden="true">✓</span><span>Link format checked</span></li><li class="is-active" aria-current="step"><span class="extraction-stage-icon" aria-hidden="true"></span><span>Finding places in the video</span></li><li class="is-pending"><span class="extraction-stage-icon" aria-hidden="true">3</span><span>Check place names and branches</span></li></ol>`}<p class="extraction-note">${fail?'The video may be private or deleted. Try a public link, or add a place using its name and address.':'Places with the same name may have different branches. Check the address in the results.'}</p><div class="buttons extraction-actions">${fail?`${btn('Search places','manual')}${btn('Try another link','home','secondary')}`:`${btn('Go back','home','secondary small')}`}</div></section>`;}
function placeCard(p,mode='result'){const chosen=state.selected.includes(p.id);return `<article class="place ${mode==='result'&&chosen?'is-selected':''}">${mode==='result'?`<input type="checkbox" aria-label="${esc(p.name)} select" data-select="${p.id}" ${chosen?'checked':''}>`:''}<div class="place-thumb">${placeArt(p)}</div><div class="place-main"><h3>${esc(p.name)}</h3><p>${esc(p.type)}${p.area&&p.area!==p.address?' · '+esc(p.area):''}</p><span class="badge ${p.verified?'':'warm'}">${pinEligible(p)?'Google Maps':'Connect a place'}</span>${!pinEligible(p)?`<button class="textbtn" data-action="resolve-place" data-id="${esc(p.id)}">Find this place on Google</button>`:''}<p>${esc(p.address)}</p><details class="place-menu"><summary aria-label="${esc(p.name)} · Manage this place"><span aria-hidden="true">⋯</span></summary><div class="place-menu-panel"><div class="buttons">${mode==='result'?`<button class="textbtn" data-action="correct" data-id="${p.id}">Connect Google place</button>`:`<button class="textbtn" data-action="correct" data-id="${p.id}">Connect Google place</button><button class="textbtn" data-action="must" data-id="${p.id}">${state.must.includes(p.id)?'★ Must-visit':'☆ Mark as must-visit'}</button><button class="textbtn" data-action="remove" data-id="${p.id}">Remove</button>`}</div></div></details>${mode==='board'?window.ReelBookingTools.widget(p):''}</div></article>`;}
function results(){const filtered=state.places.filter(p=>!p.recommended&&(state.filter==='All'||p.type===state.filter));return `${title('','Choose places','')}<p class="source-line">${state.source.startsWith('https:')?`<a href="${esc(state.source)}" target="_blank" rel="noopener noreferrer">Watch the original video ↗</a>`:'Coffee and walks in Seongsu'}</p>${mapPanel(state.selected)}<div class="sectionhead"><h2>${filtered.length} ${filtered.length===1?"place":"places"} found</h2>${btn('Search places','manual','secondary small')}</div><div class="chips">${['All','Cafes','Shopping','Food','Parks'].map(t=>chip(t,state.filter===t,`data-action="filter" data-value="${t}"`)).join('')}</div><p class="hint">Check the address for venues with multiple branches.</p>${filtered.map(p=>placeCard(p)).join('')||'<p class="empty">No places in this category yet.</p>'}<div class="bottomaction"><span>${state.selected.length} ${state.selected.length===1?"place":"places"} selected</span>${action('Save selected places','save-places','',state.selected.length?'':'disabled')}</div>`;}
function addingToTrip(){return new URLSearchParams(location.hash.split('?')[1]||'').get('from')==='trips';}
function placeSuggestion(){
 return `<details class="trip-settings"><summary>Suggest a place</summary><form class="card pad" id="suggest-place-form"><label>Place name<input name="name" required maxlength="80"></label><label>Address or neighborhood<input name="address" required maxlength="160"></label><p class="hint">Suggestions are saved only in this browser.</p><button class="btn secondary" type="submit">Save suggestion</button></form></details>`;
}
function manual(){return `<div class="place-picker-page">${placeSearchForm()}</div>`;}
function board(){ensureDays();const ids=libraryIds();return `${title('','Saved places','Choose saved places to add to your trip.',`${btn('Add video','home','secondary')}${btn('Add places','manual','secondary')}`)}<p class="collection-target"><strong>${esc(state.title)}</strong><br>Day ${state.day+1} · ${esc(state.date)} is the day you are adding places to.</p>${!ids.length?empty('No places yet.','Paste a link or add a place.'):`<section>${ids.map(place).filter(Boolean).map(p=>`<div class="library-place">${placeCard(p,'board')}<button class="btn secondary" data-action="library-to-trip" data-id="${esc(p.id)}" ${state.board.includes(p.id)?'disabled':''}>${state.board.includes(p.id)?'Added to this day':'Add to this day'}</button></div>`).join('')}<div class="bottomaction">${btn('Edit itinerary with added places','planner')}</div></section>`}`;}

const duration=ids=>ids.map(place).filter(Boolean).reduce((n,p)=>n+p.duration,0)+Math.max(0,ids.length-1)*12;
function timeAt(offset,start=state.time){const [h,m]=start.split(':').map(Number),total=h*60+m+offset;return `${String(Math.floor(total/60)%24).padStart(2,'0')}:${String(total%60).padStart(2,'0')}`;}
function timeline(ids=state.board,edit=false){let offset=0;return `<div class="timeline">${ids.map(place).filter(Boolean).map((p,i)=>{const t=timeAt(offset);offset+=p.duration+12;return `<article class="stop"><div class="stop-time">${t}</div><div class="stop-dot">${i+1}</div><div class="stop-card"><div class="timeline-cover">${placeArt(p)}<span>Seoul · ${esc(p.area)}</span></div><h3>${esc(p.name)} ${state.must.includes(p.id)?'<span class="badge">Must-visit</span>':''}</h3><p>${esc(p.type)} · ${p.duration} min${i?' · Check travel time':''}</p>${edit?`<div class="stop-controls"><button class="iconbtn" aria-label="${esc(p.name)} move up" data-action="move" data-id="${p.id}" data-dir="-1" ${i===0?'disabled':''}>↑</button><button class="iconbtn" aria-label="${esc(p.name)} move down" data-action="move" data-id="${p.id}" data-dir="1" ${i===ids.length-1?'disabled':''}>↓</button><label style="display:flex;align-items:center;gap:8px;font-weight:400">Time at stop <select data-duration="${p.id}" aria-label="${esc(p.name)} Time at stop" style="width:87px;padding:6px;min-height:32px;margin:0">${[15,30,45,50,60,90,120,180].map(n=>`<option value="${n}" ${p.duration===n?'selected':''}>${n} min</option>`).join('')}</select></label></div>`:''}</div></article>`;}).join('')}</div>`;}
// Coordinate-only estimate, not a road route or live travel time. Walking speed: 4 km/h.
function walkingEstimate(a,b){
 const valid=p=>p&&Number.isFinite(p.lat)&&Number.isFinite(p.lng)&&Math.abs(p.lat)<=90&&Math.abs(p.lng)<=180;
 if(!valid(a)||!valid(b)||(window.REEL_MAPS_CONFIG?.apiKey&&(!pinEligible(a)||!pinEligible(b))))return null;
 const rad=n=>n*Math.PI/180,dl=rad(b.lat-a.lat),dn=rad(b.lng-a.lng);
 const h=Math.sin(dl/2)**2+Math.cos(rad(a.lat))*Math.cos(rad(b.lat))*Math.sin(dn/2)**2;
 const meters=6371000*2*Math.asin(Math.sqrt(Math.min(1,Math.max(0,h))));
 return {meters,minutes:meters===0?0:Math.max(1,Math.ceil(meters/(4000/60)))};
}
function travelLeg(a,b){const e=walkingEstimate(a,b);if(!e)return '<div class="route-leg"><strong>Location needed</strong><small>Travel time needs coordinates for both stops.</small></div>';
 const directions='https://www.google.com/maps/dir/?api=1&origin='+encodeURIComponent(a.lat+','+a.lng)+'&destination='+encodeURIComponent(b.lat+','+b.lng);
 const distance=e.meters<1000?Math.round(e.meters)+' m':(e.meters/1000).toFixed(1)+' km';
 return `<div class="route-leg"><strong>About ${e.minutes} min on foot <span>· ${distance} straight-line</span></strong><a class="route-directions" href="${esc(directions)}" target="_blank" rel="noopener noreferrer" aria-label="${esc(a.name)} → ${esc(b.name)} · Directions in Google Maps">Directions ↗</a><small>${a.demoCoordinates||b.demoCoordinates?'Estimate based on example coordinates':'Estimated walk · Actual route may differ.'}</small></div>`;
}
function planner(){ensureDays();return `${title('','Edit itinerary','')}<div class="planner-tools">${btn('＋ Add video','home','secondary small')}${btn('Saved places','board','secondary small')}</div>${dayTabs()}${mapPanel()}<section class="itinerary-sheet"><div class="sheet-handle"></div><div class="sectionhead"><div><span class="eyebrow">Day ${state.day+1} · Korea time (KST)</span><h2>${state.board.length?'Stops for this day':'A new day to explore'}</h2></div><span class="badge">${state.board.length} ${state.board.length===1?"place":"places"}</span></div><details class="trip-settings"><summary><span>${state.date} · Starts at ${state.time}</span><b>Edit</b></summary><label>Trip name<input id="trip-title" value="${esc(state.title)}" maxlength="70"></label><label>Date for this day<input id="trip-date" type="date" value="${state.date}"></label><label>Start time<input id="trip-time" type="time" value="${state.time}"></label></details>${state.board.length?state.board.map((id,i)=>{const p=place(id);return `<article class="route-stop ${state.focus===id?'focused':''}"><button class="route-thumb" data-action="focus-place" data-id="${id}" aria-label="On the map: ${esc(p.name)} view">${placeArt(p).replace('loading="lazy"','loading="eager"')}<b>${i+1}</b></button><div class="route-info"><h3>${esc(p.name)}</h3><p>${esc(p.area)} · ${esc(p.type)} · ${p.duration} min</p><p class="hint">${esc(p.address)}</p><div class="route-edit"><span class="route-edit-label">Edit itinerary</span><div class="stop-controls"><button class="iconbtn" data-action="move" data-id="${id}" data-dir="-1" aria-label="${esc(p.name)} move up" ${i===0?'disabled':''}>↑</button><button class="iconbtn" data-action="move" data-id="${id}" data-dir="1" aria-label="${esc(p.name)} move down" ${i===state.board.length-1?'disabled':''}>↓</button><select data-duration="${id}" aria-label="${esc(p.name)} visit duration">${[15,30,45,50,60,90,120,180].map(n=>`<option value="${n}" ${p.duration===n?'selected':''}>${n} min</option>`).join('')}</select></div><div class="buttons"><button class="textbtn" data-action="move-day" data-id="${id}">Change day</button><button class="textbtn" data-action="remove" data-id="${id}">Remove</button></div></div>${window.ReelBookingTools.widget(p)}</div></article>${i<state.board.length-1?travelLeg(p,place(state.board[i+1])):''}`;}).join(''):`<div class="empty"><p>Move a stop from another day, or find somewhere new from a video.</p>${btn('Find places from a video','home','secondary')}</div>`}${window.ReelBookingTools.saved(state.date)}<div class="bottomaction"><div class="buttons">${action(state.saved?'Saved':'Save itinerary','save-trip',state.saved?'secondary small':'',state.saved?'disabled':'')}${state.board.length?btn('Share day','share','secondary'):''}</div></div></section>`;}
function tripText(){if(location.hash.includes('scope=trip')){stashDay();return state.title+'\n'+state.days.map((d,i)=>`Day ${i+1} · ${d.date} · ${d.time}\n${d.ids.map(place).filter(Boolean).map((p,j)=>`${j+1}. ${p.name} — ${d.durations?.[p.id]||p.duration} min`).join('\n')}${(d.notes||[]).length?'\n'+d.notes.join('\n'):''}`).join('\n\n');}return `${state.title} · Day ${state.day+1}\n${state.date} · ${state.time} (Korea time · KST)\n${state.board.map(place).filter(Boolean).map((p,i)=>`${i+1}. ${p.name} — ${p.duration} min\n${p.address}`).join('\n')}\nCheck locations and opening hours before visiting.`;}
function share(){if(!location.hash.includes('scope=trip')&&!state.board.length)return empty('No itinerary to share yet.','Add some saved places to your day first.');return `<div class="centerbox">${title('Better together','Send the plan to your travel companions.','Contact and payment details are not shared.')}<div class="card pad"><label for="share-text">Your itinerary to share</label><textarea id="share-text" style="min-height:260px" readonly>${esc(tripText())}</textarea>${taskGroup('Share with your group',action('Copy itinerary','copy'),'visit','Copy your itinerary, then paste it into your preferred messaging app.')}</div></div>`;}
function tripOverview(){stashDay();return `<section class="trip-overview"><div class="sectionhead"><div><span class="eyebrow">Whole trip · Korea time (KST)</span><h2>${esc(state.title)}</h2></div><span class="badge">${state.days.length} ${state.days.length===1?"day":"days"}</span></div>${state.days.map((d,i)=>`<article class="overview-day"><div class="overview-head"><strong>Day ${i+1} · ${esc(d.date)}</strong><button class="textbtn" data-action="overview-day" data-value="${i}">Open day →</button></div><div class="overview-stats"><div><span>Departure</span><strong>${esc(d.time)}</strong><small>KST</small></div><div><span>Stops</span><strong>${d.ids.length}</strong></div><div><span>Time at stops</span><strong>${d.ids.reduce((sum,id)=>sum+(d.durations?.[id]||place(id)?.duration||0),0)}<small> min</small></strong></div></div><ol>${d.ids.map(id=>place(id)).filter(Boolean).map(p=>`<li><span class="overview-place-name">${esc(p.name)}</span><small class="overview-duration">${d.durations?.[p.id]||p.duration} min</small></li>`).join('')||'<li>No places yet.</li>'}</ol><span class="hint overview-note">${guided&&state.booking?.date===d.date?'See the booking details below for this date.':'Self-guided · Travel and waiting times not included'}</span></article>`).join('')}${guided&&state.booking?'<p class="hint">Editing your trip does not change a confirmed mate booking.</p>':''}</section>`;}
function sampleDay(){
 return {title:signupText('sampleDay'),date:future(),time:'13:00',party:2,stops:sampleStopIds.map(id=>window.REEL_PLACES.find(p=>p.id===id))};
}
function tripWorkspace(){return `<a href="#board" class="trip-library-shortcut">${icon('board')}<span>Saved places</span><small>${isGuest()?'':libraryIds().length}</small><b aria-hidden="true">›</b></a>`;}

function tripPreview(day,cta){
 let offset=0;
 const rows=day.stops.map((p,i)=>{
  const arrival=timeAt(offset,day.time);
  offset+=p.duration+12;
  return `<li class="trip-place-row"><span class="trip-place-photo">${placeArt(p)}<b>${i+1}</b></span><div class="trip-place-copy"><strong>${esc(p.name)}</strong><span>${esc(p.area)} · ${esc(p.type)}</span><small>${p.duration} min</small></div><time>${arrival}</time></li>`;
 }).join('');
 return `<section class="card pad trip-editor-card trip-plan"><h2>${esc(day.title)}</h2><p>${esc(day.date)} · ${day.party}${signupText(day.party===1?'oneGuestUnit':'partyUnit')}</p>${rows?`<div class="trip-route-heading"><h3>Visit order</h3><span>${day.stops.length} places</span></div><ol>${rows}</ol><p class="hint">${signupText('estimateNote')}</p>`:`<div class="trip-empty"><h3>Start with a place you want to visit</h3><p>Add saved places to start planning your day.</p>${btn('Add from saved places','board','secondary')}${btn('Add a new place','manual?from=trips','secondary')}</div>`}${cta}</section>`;
}
function tripDateRange(days){const dates=days.map(d=>d.date).sort();return dates[0]===dates.at(-1)?dates[0]:dates[0]+' ~ '+dates.at(-1);}
function tripListCard(t){const ids=[...new Set(t.days.flatMap(d=>d.ids))],first=ids.map(place).find(p=>p?.photoURL||(!window.REEL_MAPS_CONFIG?.apiKey&&p?.photo));return `<button type="button" class="my-trip-card" data-action="open-trip" data-id="${esc(t.id)}"><span class="my-trip-cover">${first?placeArt(first):icon('trips')}</span><span class="my-trip-summary"><strong>${esc(t.title)}</strong><span>${esc(tripDateRange(t.days))}</span><small>${t.days.length} days · ${ids.length} places · ${t.party} guests</small></span><span class="my-trip-chevron" aria-hidden="true">›</span></button>`;}
function trips(){
 ensureDays();stashDay();stashTrip();if(isTripDetail()){const id=new URLSearchParams(location.hash.split('?')[1]).get('id');if(id&&id!==state.activeTripId&&!selectTrip(id))return empty('Trip not found.','','trips','My trip list');return tripDetail();}
 const today=new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Seoul'}),past=state.trips.filter(t=>t.days.every(d=>d.date<today)),upcoming=state.trips.filter(t=>!past.includes(t));
 return `<div class="my-trips-heading"><h1>My trips</h1></div><button class="trip-create-banner" type="button" data-action="new-trip"><span aria-hidden="true">＋</span><span><strong>Create a trip itinerary</strong><small>Start planning your next trip.</small></span></button>${tripWorkspace()}${upcoming.length?`<section class="trip-list-section"><h2>Upcoming trips</h2><div class="my-trip-list">${upcoming.map(tripListCard).join('')}</div></section>`:''}${past.length?`<section class="trip-list-section"><h2>Past trips</h2><div class="my-trip-list">${past.map(tripListCard).join('')}</div></section>`:''}`;
}
function tripDetailHeader(){return `<header class="trip-detail-header"><a class="app-back" href="#trips" aria-label="My trip list">‹</a><div><h1>${esc(state.title)}</h1><p>${esc(tripDateRange(state.days))}</p></div><button type="button" class="trip-header-icon" data-action="edit-trip" aria-label="Edit trip details"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="m4 16-1 5 5-1L21 7l-4-4L4 16ZM14 6l4 4"/></svg></button><a class="trip-header-icon" href="#share?scope=trip" aria-label="Share entire trip"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><circle cx="18" cy="5" r="3"/><circle cx="5" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><path d="m8 11 7-4m-7 6 7 4"/></svg></a></header>`;}
function tripDetail(){
 const next=activeMateStep(),linked=state.request?.tripId===state.activeTripId,stops=state.board.map(place).filter(Boolean);
 const requestAction=next?(linked?btn(next.label,next.route):btn('View your ongoing mate request',next.route,'secondary')):requestStops().length?btn(signupText('tripEstimate'),'request'):'';
 let offset=0;
 const rows=stops.map((p,i)=>{const at=timeAt(offset);offset+=p.duration+12;return `<li class="trip-timeline-stop"><span class="trip-stop-number">${i+1}</span><button class="trip-stop-content ${state.focus===p.id?'is-focused':''}" type="button" data-action="focus-place" data-id="${esc(p.id)}" aria-label="On the map: ${esc(p.name)} view"><span><strong>${esc(p.name)}</strong><small>${esc(p.type)} · ${esc(p.area)}</small><small>${at} · ${p.duration} min</small>${!pinEligible(p)?'<small class="place-connect-hint">Tap to connect a Google place</small>':''}</span><span class="trip-stop-photo">${placeArt(p)}</span></button>${i<stops.length-1?travelLeg(p,stops[i+1]):''}</li>`;}).join('');
 const notes=state.days[state.day].notes||[];
 return `<div class="trip-detail-map">${stops.length?mapPanel():'<div class="trip-map-empty">'+icon('trips')+'<p>Add places to see your route on the map.</p></div>'}</div><section class="trip-detail-sheet"><div class="sheet-handle" aria-hidden="true"></div><div class="trip-day-toolbar">${dayTabs()}${btn('편집','planner','secondary small')}</div><div class="trip-day-heading"><h2>Day ${state.day+1}</h2><span>${esc(state.date.slice(5).replace('-','.'))} · ${state.time}</span></div>${rows?`<ol class="trip-timeline">${rows}</ol>`:`<div class="trip-day-empty"><h3>Where shall we start?</h3><p>Use the + button below to add places you want to visit.</p></div>`}${notes.length?`<section class="trip-notes"><h3>Notes for this day</h3>${notes.map((note,i)=>`<button type="button" class="trip-note" data-action="edit-note" data-id="${i}"><span>${esc(note)}</span><small>Edit</small></button>`).join('')}</section>`:''}<section class="trip-mate-inline"><div>${icon('guides')}<h3>Travel with a mate</h3></div><p>Get route and price proposals for your itinerary.</p>${requestAction||'<span class="hint">Add places to request proposals.</span>'}</section></section><button class="trip-add-fab" type="button" data-action="trip-add-menu" aria-label="Add to itinerary" aria-haspopup="dialog">＋</button>`;
}
function tripAddMenu(){modal(`<div class="trip-menu-heading"><h2>Add to Day ${state.day+1}</h2><button class="textbtn" type="button" data-action="close" aria-label="Close">×</button></div><button type="button" class="trip-add-option" data-action="trip-pick-places">${icon('board')}<span><strong>Add from saved places</strong><small>Add places you found in videos to your itinerary.</small></span></button><div class="trip-add-grid"><button type="button" data-action="add-note">${icon('messages')}<strong>Add a note</strong></button><button type="button" data-action="trip-manual">${icon('all')}<strong>Add a new place</strong></button></div>`,'trip-menu');}
function tripPlacePicker(){const places=libraryIds().map(place).filter(Boolean);modal(`<div class="trip-menu-heading"><h2>Saved places</h2>${action('완료','close','secondary small')}</div><p class="hint">Day ${state.day+1} · ${esc(state.date)}</p><div class="trip-place-picker">${places.map(p=>`<div class="trip-picker-row"><span>${placeArt(p)}</span><div><strong>${esc(p.name)}</strong><small>${esc(p.area)} · ${esc(p.type)}</small></div><button class="btn secondary small" type="button" data-action="trip-add-place" data-id="${esc(p.id)}" ${state.board.includes(p.id)?'disabled':''}>${state.board.includes(p.id)?'Added':'추가'}</button></div>`).join('')||'<p>No saved places yet. Try adding a new place.</p>'}</div>`,'trip-menu');}
function addTripPlace(id){if(!libraryIds().includes(id)||!place(id)||state.board.includes(id)||state.board.length>=20)return false;state.board.push(id);state.saved=false;save();return true;}
function editTripInfo(){modal(`<form id="edit-trip-form"><h2>Edit trip details</h2><label>Trip name<input name="title" required maxlength="70" value="${esc(state.title)}"></label><label>Start date<input name="date" type="date" required value="${esc(state.days[0].date)}"></label><label>Guests<select name="party">${[1,2,3,4].map(n=>`<option value="${n}" ${state.party===n?'selected':''}>${n} ${n===1?"guest":"guests"}</option>`).join('')}</select></label><p class="hint">Changing the start date shifts every day by the same amount.</p><p id="edit-trip-error" role="alert" class="error"></p><div class="buttons"><button type="submit" class="btn">Save</button>${action('Cancel','close','secondary')}</div></form>`);}
function updateTripInfo(d){const name=String(d.title||'').trim(),party=Number(d.party),date=d.date;if(!name||name.length>70||!/^\d{4}-\d{2}-\d{2}$/.test(date||'')||!Number.isFinite(Date.parse(date+'T12:00:00Z'))||dateAfter(date,0)!==date||!Number.isInteger(party)||party<1||party>4)return false;stashDay();const shift=Math.round((Date.parse(date)-Date.parse(state.days[0].date))/86400000);state.days.forEach(day=>day.date=dateAfter(day.date,shift));state.date=state.days[state.day].date;state.title=name;state.party=party;state.saved=false;save();return true;}
function editTripNote(index=-1){const note=(state.days[state.day].notes||[])[index]||'';modal(`<form id="trip-note-form" data-index="${index}"><h2>Day ${state.day+1} note</h2><label>Note<textarea name="note" required maxlength="500" placeholder="Write down meeting points, booking times, or things to bring.">${esc(note)}</textarea></label><p id="note-error" class="error" role="alert"></p><div class="buttons"><button type="submit" class="btn">Save</button>${action('Cancel','close','secondary')}</div></form>`);}
function saveTripNote(text,index=-1){const note=String(text||'').trim();if(!note||note.length>500)return false;stashDay();const notes=state.days[state.day].notes||(state.days[state.day].notes=[]);if(index>=0){if(index>=notes.length)return false;notes[index]=note;}else notes.push(note);state.saved=false;save();return true;}

let guidesTab='requests';
function guideRequests(){const r=state.request,list=proposals(),open=r&&['requested','quoted'].includes(r.status)&&!state.booking;return `<div class="proposal-inbox"><div class="inbox-heading"><h2>Received proposals</h2><a href="#support">Service information</a></div><section class="request-group"><h3>Receiving proposals</h3>${open?requestInboxCard(r,list,true):`<button type="button" class="inbox-start" data-action="guides-tab" data-id="discover"><span class="inbox-start-icon">${icon('board')}</span><span><strong>No proposals yet</strong><small>지역과 Trip length만 정해 자유 견적을 받아보세요.</small></span><b aria-hidden="true">›</b></button>`}</section>${r&&!open?`<section class="request-group"><h3>Closed requests</h3><p class="request-group-note">This trip is no longer receiving proposals.</p>${requestInboxCard(r,list,false)}</section>`:''}</div>`;}
function requestInboxCard(r,list,open){const unread=list.filter(q=>!(state.viewedProposals||[]).includes(q.id+':'+q.version));const created=r.createdAt?new Date(r.createdAt).toLocaleDateString(document.documentElement.lang==='en'?'en-US':'ko-KR',{timeZone:'Asia/Seoul',month:'short',day:'numeric'}):'';return `<a href="#requested" class="request-inbox-card"><div class="request-inbox-meta"><span class="request-inbox-status ${open?'is-open':''}">${open?'Receiving proposals':state.booking?'Mate selected':'Close request'}</span><span>${esc(created)}</span></div><div class="request-inbox-title"><h4>${esc(r.tripTitle||state.title)}</h4><span>Proposals ${list.length} <b aria-hidden="true">›</b></span></div><p class="request-inbox-facts">${requestPeriod(r)} · ${r.party} ${r.party===1?"guest":"guests"} · ${r.requestType==='free'?'자유 견적':(r.stops||[]).length+' places'}</p><div class="request-inbox-footer">${list.length?`<span class="proposal-avatar-stack" aria-hidden="true">${list.slice(0,3).map(q=>`<span>${esc(q.guide[0])}</span>`).join('')}</span><span>${unread.length?'New proposals '+unread.length:'Compare received proposals'}</span>`:'<span>Mates are reviewing your trip</span>'}</div></a>`;}


const nicknameDirectoryKey='reeltrip-prototype-nicknames-v1',nicknameOwner='traveler-demo';
let checkedNickname='';
const normalizeNickname=value=>String(value||'').normalize('NFKC').replace(/\s+/gu,'').toLowerCase();
function readNicknameDirectory(){const raw=JSON.parse(localStorage.getItem(nicknameDirectoryKey)||'{}');if(!raw||typeof raw!=='object'||Array.isArray(raw))throw new Error('Invalid nickname directory');return {...raw,[normalizeNickname('\uBBF8\uB098')]:'mate-mina',[normalizeNickname('\uC900')]:'mate-jun'};}
function nicknameProblem(value,directory){const display=String(value||'').normalize('NFKC').trim(),canonical=normalizeNickname(display);if(display.length<2||display.length>20||canonical.length<2)return 'Enter a nickname with 2–20 characters.';if(/[\p{Cc}\p{Cf}]/u.test(display))return 'This nickname contains unsupported characters.';if(['\uB9B4\uD2B8\uB9BD','reeltrip','\uC6B4\uC601\uD300','\uACE0\uAC1D\uC13C\uD130','\uAD00\uB9AC\uC790'].some(word=>canonical.includes(word)))return 'Names that could impersonate staff are not allowed.';const owner=directory[canonical];return owner&&owner!==nicknameOwner?'This nickname is taken. Try another name.':'';}
function checkNickname(){const input=document.querySelector('#profile-form [name="nickname"]'),message=$('#nickname-status');checkedNickname='';try{const problem=nicknameProblem(input.value,readNicknameDirectory());message.textContent=problem||'This nickname is available.';message.dataset.valid=String(!problem);if(!problem)checkedNickname=normalizeNickname(input.value);}catch{message.textContent='Could not check availability. Please try again.';message.dataset.valid='false';}}
let profileDraftPhoto='';
function profileAvatar(photo=state.profile?.photo){return photo?`<img src="${esc(photo)}" alt="Profile photo">`:icon('account');}
function editProfile(){checkedNickname='';profileDraftPhoto=state.profile?.photo||'';modal(`<form id="profile-form"><div class="profile-dialog-heading"><h2>Edit profile</h2><button type="button" class="textbtn" data-action="close" aria-label="Close">×</button></div><div class="profile-photo-editor"><div class="profile-photo-preview" id="profile-photo-preview">${profileAvatar(profileDraftPhoto)}</div><label class="profile-camera-button" id="profile-camera-button" aria-label="Choose photo" ${profileDraftPhoto?'hidden':''}>${icon('camera')}<span class="sr-only">Choose photo</span><input id="profile-photo" type="file" accept="image/jpeg,image/png,image/webp"></label><button type="button" class="profile-photo-clear" id="profile-photo-clear" data-action="remove-profile-photo" aria-label="Remove photo" ${profileDraftPhoto?'':'hidden'}><span aria-hidden="true">×</span></button></div><p class="hint">JPG·PNG·WebP · Up to 1MB</p><label for="profile-nickname">Nickname</label><div class="nickname-entry"><input id="profile-nickname" name="nickname" required minlength="2" maxlength="20" value="${esc(state.profile?.nickname||'')}" placeholder="What should we call you?" autocomplete="nickname" aria-describedby="nickname-status"><button type="button" class="nickname-check" data-action="check-nickname">Check availability</button></div><p id="nickname-status" class="nickname-status" role="status" aria-live="polite"></p><p id="profile-error" class="error" role="alert"></p><button type="submit" id="profile-save" class="btn">Save</button></form>`);}
function account(){const mate=window.ReelAccess.mode()==='guide',booking=state.booking,request=state.request;const activeBooking=booking&&['awaiting_mate_fee','confirmed','cancellation_requested'].includes(booking.status),activeRequest=!activeBooking&&request&&['requested','quoted'].includes(request.status);return `<section class="my-page"><div class="my-heading"><h1>My account</h1><a class="my-settings-button" href="#settings" aria-label="Settings">${icon('settings')}</a></div><button type="button" class="my-profile" data-action="edit-profile" aria-label="Edit profile"><span class="my-avatar">${profileAvatar()}</span><span class="my-profile-copy"><strong>${esc(state.profile?.nickname||'Traveler')}</strong><small>${state.profile?.nickname?'Edit profile':'Add your nickname and photo'}</small></span><span class="profile-edit-chevron" aria-hidden="true">›</span></button>${activeBooking||activeRequest?`<section class="my-current"><span class="eyebrow">Your ongoing trip</span><h2>${esc(activeBooking?booking.date:request.tripTitle||state.title)}</h2><p>${esc(statusLabel(activeBooking?booking.status:request.status))}${activeRequest?' · '+proposals().length+'개의 Proposals':''}</p>${mate?btn('View request','guide-desk','secondary'):activeBooking?btn('View booking','booking','secondary'):'<a class="btn secondary" href="#guides" data-action="my-proposals">View received proposals</a>'}</section>`:''}<div class="my-menu">${mate?`<a href="#guide-calendar">Manage availability<span>›</span></a><a href="#guide-earnings">Matching fee<span>›</span></a>`:`<a href="#guides" data-action="my-proposals">Received proposals<span>${proposals().length?proposals().length+' · ':''}›</span></a>`}</div></section>`;}

function settingsPage(){return `<section class="settings-page">${window.ReelAccess.settings().replace(/<div class="account-setting-row">[\s\S]*?<\/a><\/div>/,()=>signupLanguageLink())}<section class="settings-group"><h2>Help & information</h2><a href="#support">Help and support<span>›</span></a><a href="#policies">Terms and privacy<span>›</span></a></section><section class="settings-group"><h2>Manage data</h2><button type="button" data-action="export-data">Download my data<span>↓</span></button><button type="button" data-action="reset" class="settings-danger">Delete saved data<span>›</span></button></section></section>`;}

function support(){return `<div class="centerbox">${title('Help','How can we help?','')}<div class="card pad"><h2 class="support-group-title">Common questions</h2><details><summary>Can I find a place without knowing its Korean name?</summary><p class="muted small">A public video link can suggest places. Some videos cannot be analyzed. If several branches share a name, compare their addresses.</p></details><details style="margin-top:16px"><summary>${guided?'Can my mate book a restaurant for me?':'Does saving a place reserve a table?'}</summary><p class="muted small">${guided?'Saving a place or requesting a mate does not reserve a table. Describe the help you need and check what is included in the final proposal.':'Saving places helps you plan visits. Restaurant bookings and ordering assistance are not included. Check reservation requirements with the venue.'}</p></details><details style="margin-top:16px"><summary>Why was a place not found?</summary><p class="muted small">Private videos, unclear names or multiple branches can make places hard to identify. Try a public link or add a place yourself.</p></details></div><form id="support-form" class="card pad" style="margin-top:20px"><h2 class="support-group-title">Write a message</h2><label>Topic<select name="type"><option>Place or video issue</option><option>Data or privacy request</option>${guided?'<option>Booking or refund</option>':''}<option>Other feedback</option></select></label><label style="margin-top:17px">How can we help?<textarea name="body" minlength="10" maxlength="1000" required placeholder="Which place or step do you need help with? Write in the language you are comfortable with. At least 10 characters."></textarea></label><button type="submit" class="btn" style="margin-top:18px">Save message</button></form>${state.tickets.length?`<div class="notice">${state.tickets.length} saved messages. Latest status: ${esc(statusLabel(state.tickets.at(-1).status))}. Not sent to support.</div>`:''}</div>`;}
function policies(){return `<article class="legalcopy">${title('Service information','Before you travel.','Place information와 Save 방식, 현금 지급·매칭 방식을 Information합니다.')}<h2>Places and maps</h2><p>Photos and maps help you explore. Check current hours, the correct branch and entrance before visiting. Map lines show visit order, not actual directions.</p><h2>Saving your trip</h2><p>Your trip is saved in this browser only. It does not sync automatically and may be lost if browser data is cleared. Download or delete it from My account.</p><h2>What is connected</h2><p>Video analysis, live directions and support messages are not connected yet.${guided?' Request a mate과 Message는 이 기기에만 Save됩니다. 실제 Mates 연락·Bookings·Matching fee 결제는 발생하지 않습니다. 여행 비용은 현장에서 Mates에게 현금으로 지급하는 구조입니다.':''}</p><h2>Privacy</h2><p>Do not enter real payment details or sensitive personal information. Shared itineraries do not include your contact details or conversations.</p><h2>Photos and content</h2><p>Open the original video using its link. Photos may not reflect how a place looks today.</p><div class="buttons"><a class="btn secondary" href="../docs/photo-credits.html">Photo credits</a>${btn('Help','support','secondary')}</div></article>`;}
function guides(){return `${title('','Mates')}<div class="trip-mode-tabs" role="group" aria-label="Mate menu"><button type="button" data-action="guides-tab" data-id="requests" aria-pressed="${guidesTab==='requests'}">${icon('board')}<span>Received proposals</span>${proposals().length?`<span class="trip-request-count">${proposals().length}</span>`:''}</button><button type="button" data-action="guides-tab" data-id="discover" aria-pressed="${guidesTab==='discover'}">${icon('guides')}<span>자유 견적 받기</span></button></div><section class="trip-tab-panel">${guidesTab==='requests'?guideRequests():guideDiscovery()}</section>`;}

function guideDiscovery(){const next=activeMateStep();return `<section class="card pad free-quote-intro"><span class="eyebrow">No itinerary needed</span><h2>Where are you going, and for how long?</h2><p>지역과 Trip length을 알려주면 Mates가 코스와 All 견적을 Proposals해요.</p><ul class="listclean"><li>Choose your destination</li><li>Choose a day trip or a multi-day trip</li><li>Compare routes and prices, then select a mate</li></ul>${next?`<p class="notice">Review your current request or booking first.</p>${btn(next.label,next.route)}`:btn('지역·기간 정하고 자유 견적 받기','request?mode=free')}<p class="hint">Already have an itinerary? Request proposals from My trips.</p>${btn('View my trips','trips','secondary')}</section>`;}



function journeySummary(q,priceLabel='Total for your group'){return `<section class="journey-summary"><div class="journey-guide"><span class="portrait">${esc(q.guide[0])}</span><div><h2>${esc(q.guide)}${q.guide==='Not matched yet'?'':' Mates'}</h2><p>English Information · ${esc(q.region||'Destination')}</p></div></div><div class="journey-facts"><div><span>Travel date</span><strong>${requestPeriod(q)}</strong></div><div><span>Start time · KST</span><strong>${esc(q.time)}</strong></div><div><span>Your group</span><strong>${q.party} ${q.party===1?"guest":"guests"}</strong></div><div><span>Request type</span><strong>${q.requestType==='free'?'자유 견적':'My itinerary'}</strong></div></div>${q.amount!==undefined?`<div class="journey-price"><span>${priceLabel} · KRW</span><strong>${money(q.amount)}</strong><p>Total for ${q.party} ${q.party===1?"guest":"guests"}. Food, transport, shopping and entry fees are extra.</p></div>`:`<div class="journey-price pending"><span>Mate fee</span><strong>Price on request</strong><p>No payment now. Review your proposal before booking.</p></div>`}</section>`;}
function journeyPlan(plan){return `<ol class="journey-plan">${String(plan||'').split('\n').filter(line=>line.trim()).map((line,i)=>`<li><b>${i+1}</b><span>${esc(line.replace(/^\d+[.)]\s*/,''))}</span></li>`).join('')}</ol>`;}
function guidePage(){
 const mate=state.guide==='jun'?'jun':'mina';
 const photo=guide().photo;
 return `${title('','Meet your mate','')}
 <section class="mate-profile">
  <header class="mate-cover mate-cover--${mate}">
   <div class="mate-identity">
    ${photo?`<img class="mate-avatar" src="${esc(photo)}" alt="">`:''}
    <div><p class="mate-area">${signupText(mate+'Area')}</p><h2>${signupText(mate+'Title')}</h2></div>
   </div>
  </header>
  <div class="mate-bio">
   <p class="mate-intro">${signupText(mate+'Intro')}</p>
   <p class="mate-meta">${signupText('mateLanguages')}<br>${signupText('mateCapacity')}</p>
   <p class="mate-price-note">${signupText('matePriceNote')}</p>
  </div>
 </section>
 <section class="mate-help"><h2>How your mate can help</h2><ul>
  <li>${icon('guides')}<span>Explore the neighborhood in English</span></li>
  <li>${icon('cafe')}<span>Get help ordering in Korean at cafes and restaurants</span></li>
  <li>${icon('trips')}<span>Plan a practical visit order and find your way</span></li>
 </ul><p class="hint">Food, shopping, transport and entry fees are extra. Availability is checked after you request.</p></section>`;
}

function requestPeriod(r){return r.endDate&&r.endDate!==r.date?`${esc(r.date)} ~ ${esc(r.endDate)}`:esc(r.date);}
function tripLength(n){return n===1?'Day trip':`${n-1} nights / ${n} days`;}
function dateAfter(date,offset){return new Date(Date.parse(date+'T12:00:00Z')+offset*86400000).toISOString().slice(0,10);}
function itineraryRequestDays(example=false){
 if(example){const d=sampleDay();return [{date:d.date,time:d.time,stops:d.stops.map(p=>({...p}))}];}
 stashDay();return state.days.map(d=>({date:d.date,time:d.time,stops:d.ids.map(place).filter(Boolean).map(p=>({...p,duration:d.durations?.[p.id]||p.duration}))}));
}
function requestPlan(r){return (r.days?.length?r.days:[{date:r.date,stops:r.stops||[]}]).map((d,i)=>`Day ${i+1} · ${d.date}\n${d.stops.length?d.stops.map(p=>p.name+' · '+p.duration+' min').join('\n'):'Your mate will propose places to visit.'}`).join('\n');}
function submitTravelRequest(d,{free=false,example=false}={}){
 if(activeMateStep())return {route:activeMateStep().route};
 let days=free?[]:itineraryRequestDays(example);
 const count=Number(d.dayCount),party=Number(d.party),region=String(d.region||'').trim();
 if(free&&(!region||region.length>80))return {error:'Enter your destination.'};
 if(free&&(!Number.isInteger(count)||count<1||count>7))return {error:'Choose a trip length from 1 to 7 days.'};
 if(!Number.isInteger(party)||party<1||party>4)return {error:'Choose 1 to 4 travelers.'};
 const start=free?d.date:days[0]?.date,time=free?d.time:days[0]?.time;
 if(!/^\d{4}-\d{2}-\d{2}$/.test(start||'')||!/^([01]\d|2[0-3]):[0-5]\d$/.test(time||'')||!Number.isFinite(Date.parse(`${start}T${time}:00+09:00`))||Date.parse(`${start}T${time}:00+09:00`)<Date.now()+48*3600000)return {error:'Choose a start date and time at least 48 hours from now.'};
 if(dateAfter(start,0)!==start)return {error:'Choose a valid date.'};
 if(free)days=Array.from({length:count},(_,i)=>({date:dateAfter(start,i),time,stops:[]}));
 if(!days.length||days.length>7||days.some((day,i)=>!Number.isFinite(Date.parse(day.date+'T12:00:00Z'))||(i&&day.date<=days[i-1].date))||Date.parse(days.at(-1).date)-Date.parse(start)>6*86400000)return {error:'Arrange your itinerary dates in order within a 7-day period.'};
 const stops=days.flatMap(day=>day.stops);
 if(!free&&!stops.length)return {error:'Add saved places to your trip first.'};
 if(!free&&days.some(day=>day.stops.length>20))return {error:'You can request up to 20 places per day.'};
 if(!d.guideAck||!d.ack)return {error:'Confirm the sharing and booking request notices.'};
 syncConversations();
 state.request={id:'RQ-DEMO-'+Date.now(),status:'requested',requestType:free?'free':'itinerary',region:free?region:[...new Set(stops.map(p=>p.area))].join(', '),date:start,endDate:days.at(-1).date,dayCount:days.length,time,party,days:JSON.parse(JSON.stringify(days)),notes:String(d.notes||'').trim().slice(0,500),guide:'Not matched yet',guideId:null,tripId:free?null:(state.activeTripId||'trip-legacy'),tripTitle:free?region+' · '+tripLength(days.length):example?signupText('sampleDay'):state.title,language:d.language||'English',stops:JSON.parse(JSON.stringify(stops)),must:free||example?[]:state.must.filter(id=>stops.some(p=>p.id===id)),createdAt:Date.now()};
 state.quote=null;state.proposals=[];state.booking=null;state.review=null;state.messages=[];state.rating=0;save();return {route:'requested'};
}
function request(){
 const next=activeMateStep();if(next)return empty('You have an ongoing trip.','Review your request or booking status first.',next.route,next.label);
 const params=new URLSearchParams(location.hash.split('?')[1]||''),free=params.get('mode')==='free',example=params.get('sample')==='1',days=free?[]:itineraryRequestDays(example);
 if(!free&&!days.some(d=>d.stops.length))return empty('Your trip has no places yet.','Add places or ask a mate to propose your route.','request?mode=free','자유 견적 받기');
 return `${steps(0)}${title('',free?'자유 견적 요청':'Request a mate for my trip',free?'Choose a destination and trip length. Mates will propose a route.':'Share the places in your daily itinerary with mates.')} ${free?'':`<section class="handoff card pad"><span class="badge">Trip overview · ${days.length} days</span><h2>${esc(example?signupText('sampleDay'):state.title)}</h2>${days.map((d,i)=>`<h3>Day ${i+1} · ${esc(d.date)}</h3><p>${d.stops.map(p=>esc(p.name)).join(' · ')||'Ask your mate to suggest a route.'}</p>`).join('')}${example?'':btn('Edit my trip',tripDetailRoute(),'secondary small')}</section>`}<form id="request-form" class="card pad" data-request-type="${free?'free':'itinerary'}"><h2>Your travel details</h2>${free?`<label>Destination<input name="region" required maxlength="80" placeholder="e.g. Seongsu in Seoul, Busan, Jeju"></label><div class="formrow"><label>Start date<input type="date" name="date" required value="${future()}"></label><label>Trip length<select name="dayCount">${[1,2,3,4,5,6,7].map(n=>`<option value="${n}">${tripLength(n)}</option>`).join('')}</select></label></div><label>First-day meeting time (Korea)<input type="time" name="time" required value="10:00"></label><p class="hint">Nights describe the trip length. Accommodation and 24-hour accompaniment are not included.</p>`:''}<div class="formrow"><label>Guests<select name="party">${[1,2,3,4].map(n=>`<option value="${n}" ${state.party===n?'selected':''}>${n} ${n===1?"guest":"guests"}</option>`).join('')}</select></label><label>Tour language<select name="language"><option>English</option></select></label></div><label>Activities or help needed (optional)<textarea name="notes" maxlength="500" placeholder="e.g. Food, shopping, ordering in Korean, must-visit places"></textarea></label><label class="check"><input type="checkbox" name="guideAck" required>I agree to share my trip preferences and request with mates.</label><label class="check"><input type="checkbox" name="ack" required>I will review the proposed route and total price before selecting a mate.</label><p class="hint">Request at least 48 hours before departure. Sending a request does not book or charge you.</p><p id="request-error" class="error" role="alert"></p><button type="submit" class="btn">${free?'자유 견적 요청하기':'Get mate proposals for this trip'}</button></form>`;
}

function requested(){const r=state.request;if(!r)return empty('No mate requests yet.','My trips으로 Proposals을 받아보세요.','request','Find a travel mate');const list=proposals();return `${title('','Received proposals','Compare itineraries, inclusions and the total price.')}<section class="card pad request-summary-card"><span class="badge">${esc(statusLabel(r.status))}</span><h2>${esc(r.tripTitle||state.title)}</h2><p>${requestPeriod(r)} · ${r.party} ${r.party===1?"guest":"guests"} · ${r.requestType==='free'?'자유 견적':(r.stops||[]).length+' places'}</p>${state.booking||r.status==='booked'?btn('View booking','booking'):['requested','quoted'].includes(r.status)?action('Close request','withdraw','secondary small'):btn('Find a travel mate','request')}</section>${list.length?`<div class="proposal-section-heading"><h2>Mate proposals</h2><span>${list.length}</span></div><div class="proposal-grid">${list.map(q=>`<article class="card pad proposal-card"><div class="guide proposal-header"><span class="portrait">${esc(q.guide[0])}</span><div><h2>${esc(q.guide)}${q.guide==='Not matched yet'?'':' Mates'}</h2><p>English · ${esc(q.region||'Destination')}</p></div></div><p class="proposal-description">${esc(q.reason)}</p><strong class="proposal-price">${money(q.amount)}<small> / ${q.party} ${q.party===1?"guest":"guests"} All</small></strong><p class="hint proposal-validity">${q.expires>Date.now()?'Proposal available':'Expired'}</p>${action('View plan & proposal','select-proposal','secondary',`data-id="${esc(q.id)}"`)}</article>`).join('')}</div>`:`<div class="empty"><h2>Waiting for mate proposals</h2><p>Mates will review your trip and send their plans and proposals.</p></div>`}${!state.booking&&['requested','quoted'].includes(r.status)?`<details class="demo-next"><summary>Try sample proposals</summary>${action('Generate sample proposals','demo-proposals','secondary')}</details>`:''}`;}

function quoteValid(){return state.quote&&state.quote.expires>Date.now()&&state.request?.status==='quoted';}
function quote(){const q=state.quote;if(!q)return empty('No proposal yet.','Your itinerary and proposal will appear here once your mate has reviewed your request.','requested','View request');const valid=quoteValid();return `${steps(1)}${title('Your mate proposal','Your itinerary and price.',`Proposals ${q.version} · ${state.booking?'Accepted proposal':valid?'Valid for 24 hours after issue':'Expired or withdrawn proposal'}`)}${journeySummary(q,'Cash payable in person')}${action('Ask this mate','open-proposal-chat','secondary',`data-id="${esc(q.id)}"`)}<section class="card pad"><h2>Your proposed itinerary</h2>${journeyPlan(q.plan)}<details class="trip-settings"><summary><span>Compare with your request</span><b>view</b></summary>${journeyPlan(state.request?requestPlan(state.request):'')}</details><div class="notice"><strong>What changed and why</strong><p>${esc(q.reason)}</p></div></section><section class="card pad"><h2>Included in the price</h2>${taskGroup('Included',`<ul class="listclean"><li>${window.ReelRevenue.duration(q.pricing?.hours||4)}</li><li>Itinerary preparation and help getting around and ordering</li></ul>`,'visit')}${taskGroup('Not included','<p>Food, shopping, transport and entry fees</p><p class="hint">Venue reservations and skip-the-line access are not guaranteed.</p>','caution')}</section><details class="card pad journey-terms"><summary>Cash payment & cancellations</summary><p>Pay in cash in person. Discuss cancellations or return of cash already paid with your mate.</p></details><div class="bottomaction journey-action"><p>${state.booking?'Reviewed proposal':valid?'Total for your group · '+money(q.amount):'A new, valid proposal is needed'}</p>${state.booking?btn('View booked itinerary','booking'):valid?btn('Continue to booking','checkout'):btn(signupText('compareOffers'),'requested','secondary')}</div>`;}

function requestBooking(name,email){if(window.ReelAccess.isAdmin||window.ReelAccess.mode()!=='customer'||state.booking||!quoteValid())return false;const q=state.quote;state.booking={...JSON.parse(JSON.stringify(q)),requestId:state.request.id,id:'RT-DEMO-'+Date.now(),quoteVersion:q.version,status:'awaiting_mate_fee',customer:name,email,requestedAt:Date.now(),paymentMethod:'cash',feeRate:.1,feeAmount:Math.round(q.amount*.1),feeStatus:'pending',cashStatus:'uncollected',policyVersion:'CASH-MATCH-10-V1'};syncConversations();state.request.status='matching';state.request.guide=q.guide;state.request.guideId=q.guideId;save();return true;}
function confirmMateFee(outcome){const b=state.booking;if(window.ReelAccess.isAdmin||window.ReelAccess.mode()!=='guide'||!b||b.status!=='awaiting_mate_fee'||b.feeStatus==='paid')return false;if(outcome!=='success'){b.feeStatus='failed';save();return false;}b.feeStatus='paid';b.feePaidAt=Date.now();b.status='confirmed';b.confirmedAt=Date.now();state.request.status='booked';save();return true;}
function cashNotice(amount){return `<section class="card pad cash-notice"><span class="badge">Cash payment in person</span><h2>Bring cash on your trip day</h2><strong>${money(amount)}</strong><p>Pay your mate directly in cash. Reeltrip connects you and does not collect the trip fee.</p></section>`;}
function guideFee(){const b=state.booking;if(!b)return side('guide',empty('No booking has been selected.','You can pay the fee after a traveler selects you.','guide-desk','Requests'));return side('guide',`${title('','Confirm the match','The traveler selected your proposal.')}${journeySummary(b,'Cash to receive in person')}<section class="card pad"><h2>10% matching fee</h2><div class="summaryrow"><span>Agreed trip price</span><b>${money(b.amount)}</b></div><div class="summaryrow total"><span>Matching fee payable to Reeltrip</span><b>${money(b.feeAmount)}</b></div><p>Pay the matching fee to confirm the booking. Collect the trip price directly from the traveler in cash.</p>${b.status==='awaiting_mate_fee'?`<form id="mate-fee-form">${b.feeStatus==='failed'?`<p role="status">${signupText('feeRetry')}</p>`:''}<label class="check"><input type="checkbox" name="terms" required>I understand the 10% matching fee and direct cash payment.</label><label class="developer-only">Payment outcome<select name="outcome"><option value="success">Payment success</option><option value="failure">Payment failed</option></select></label><p id="mate-fee-error" class="error" role="alert"></p><button type="submit" class="btn">${money(b.feeAmount)} Pay and confirm booking</button></form>`:`<p>${b.feeStatus==='paid'?'Matching fee paid':'Payment is unavailable for the current status.'}</p>`}</section>`);}
function checkout(){if(state.booking)return empty('This proposal already has a booking request.','Open the booking to check its current status.','booking','Open booking');if(!quoteValid())return empty('You need a valid proposal.','Ask your mate for an updated itinerary and price.','quote','View proposal');const q=state.quote;return `${steps(2)}${title('','Select mate & request booking','The booking is confirmed once your mate pays the matching fee.')}${journeySummary(q,'Cash payable in person')}<form id="checkout-form" class="card pad"><h2>Traveler details</h2><label>Your name<input name="name" required maxlength="60" value="${esc(state.profile?.nickname||'')}" autocomplete="name"></label><label>Email<input name="email" type="email" required autocomplete="email"></label><label class="check"><input name="terms" type="checkbox" required>I agree to the itinerary and total price and will pay my mate in cash on the trip day.</label><label class="check"><input name="pendingAck" type="checkbox" required>I understand this is a booking request, confirmed only after the mate pays the matching fee.</label><p id="checkout-error" class="error" role="alert"></p><button type="submit" class="btn">Select mate & request booking</button></form>`;}

function booking(){const b=state.booking;if(!b)return empty('No bookings yet.','Mates의  days정과 가격을 확인한 뒤 Bookings을 요청하세요.','requested','View request');const pending=b.status==='awaiting_mate_fee',confirmed=['confirmed','completed'].includes(b.status);return `${title('Your guided trip',pending?'Waiting for your mate to confirm':statusLabel(b.status),b.id)}${pending?'<div class="notice">Your booking is pending until your mate pays the matching fee.</div>':''}${journeySummary(b,'Cash payable in person')}${confirmed?'<p class="notice">Pay your mate directly in cash on the day of your trip.</p>':''}${confirmed?`<section class="meeting-card"><span class="badge">Where to meet</span><h2>Arrange your meeting point with your mate</h2><p>${requestPeriod(b)} · First day ${b.time} / Korea time (KST)</p><p class="hint">Confirm your first meeting point and daily mate hours in chat.</p></section>`:''}<section class="card pad"><h2>${pending?'Requested itinerary':'Booked itinerary'}</h2>${journeyPlan(b.plan)}</section>${pending?btn(signupText('backTrips'),'trips','secondary small'):''}${['awaiting_mate_fee','confirmed'].includes(b.status)?`<section class="card pad">${btn(pending?'Withdraw booking request':'Cancel booking','cancel','secondary')}</section>`:''}${b.status==='cancellation_requested'?'<div class="notice">Your cancellation request is under review. Contact your mate about any cash already paid.</div>':''}${!confirmed||b.status==='completed'&&!state.review?btn('Chat with mate','chat','secondary'):''}${confirmed?`<div class="bottomaction journey-action">${b.status==='completed'&&!state.review?btn('Review your trip','review'):btn('Message your mate','chat')}</div>`:''}${state.review?`<section class="card pad"><h2>My review · ${state.review.rating}/5</h2><p>${esc(state.review.body)}</p></section>`:''}`;}

function sampleChatMessages(){return [
 {sender:'guide',text:'Hi! I’m Mina, your mate for the Seongsu trip. Nice to meet you!',at:1795051800000},
 {sender:'customer',text:'Hi! I’d like to walk through Seoul Forest and visit a quiet cafe.',at:1795051920000},
 {sender:'guide',text:'Sounds great. We’ll walk through Seoul Forest, then visit a nearby cafe. I’ll show you some photo spots too.',at:1795052100000},
 {sender:'customer',text:'Great! Where should we meet?',at:1795052220000},
 {sender:'guide',text:'Let’s meet at Seoul Forest Station, Exit 4, at 1 PM. Message me here when you arrive!',at:1795052400000}
 ];}
// Conversation IDs are stable across proposal revisions and booking confirmation.
function conversationKey(requestId,guideId){return JSON.stringify([requestId,guideId]);}
function ensureConversation(q,requestId=state.request?.id){
 if(!requestId||!q)return null;
 if(!Array.isArray(state.conversations))state.conversations=[];
 const guideId=q.guideId||'mina',id=conversationKey(requestId,guideId);
 let room=state.conversations.find(c=>c.id===id);
 if(!room){room={id,requestId,guideId,guide:q.guide,tripTitle:q.tripTitle||state.request?.tripTitle||state.title,endDate:q.endDate||q.date,date:q.date,customer:state.profile?.nickname||'Traveler',messages:[],read:{customer:0,guide:0},createdAt:Date.now()};state.conversations.push(room);}
 return room;
}
function syncConversations(){
 if(isGuest())return [];
 if(!Array.isArray(state.conversations))state.conversations=[];
 const b=state.booking;
 if(b){
  const requestId=b.requestId||state.request?.id||b.id;
  const room=ensureConversation(b,requestId);
  if(room){
   room.bookingId=b.id;room.customer=b.customer||room.customer;room.status=b.status;
   // Keep the old storage field compatible, importing its history only once.
   if(!room.legacyImported){if(!room.messages.length&&state.messages?.length)room.messages=state.messages.map(m=>({...m,sender:m.sender||'customer'}));room.legacyImported=true;}
  }
 }
 return state.conversations;
}
function conversationBooking(room){const b=state.booking;return b&&conversationKey(b.requestId||state.request?.id||b.id,b.guideId||'mina')===room.id?b:null;}
function conversationOpen(room){
 const b=conversationBooking(room);
 if(b)return ['awaiting_mate_fee','confirmed'].includes(b.status);
 return room.requestId===state.request?.id&&!state.booking&&['requested','quoted'].includes(state.request.status);
}
function conversationStatus(room){const b=conversationBooking(room);return b?statusLabel(b.status):conversationOpen(room)?'Proposal discussion':'Closed conversation';}
function conversationRoute(room){return 'chat?thread='+encodeURIComponent(room.id);}
function conversationUnread(room){const mode=window.ReelAccess.mode();return room.messages.slice(room.read?.[mode]||0).filter(m=>(m.sender||'customer')!==mode).length;}
function unreadChats(){return isGuest()?0:syncConversations().reduce((sum,room)=>sum+conversationUnread(room),0);}
function chatContext(){
 const params=new URLSearchParams(location.hash.split('?')[1]||''),rooms=syncConversations();
 if(!isGuest()&&params.has('thread')){const room=rooms.find(c=>c.id===params.get('thread'));return room?{sample:false,room,booking:conversationBooking(room)||room,messages:room.messages}:null;}
 if(!isGuest()&&params.get('sample')!=='1'&&state.booking){const room=rooms.find(c=>conversationBooking(c));if(room)return {sample:false,room,booking:state.booking,messages:room.messages};}
 return {sample:true,booking:{guide:'Mina',customer:'Jamie',tripTitle:'A slow afternoon in Seongsu',date:future(),status:'confirmed'},messages:isGuest()?sampleChatMessages():(state.sampleMessages||sampleChatMessages())};
}
function markChatRead(){
 if(isGuest()||window.ReelAccess.isAdmin||current()!=='chat')return;
 const context=chatContext();if(!context||context.sample)return;
 const room=context.room,mode=window.ReelAccess.mode();room.read=room.read||{};
 if(room.read[mode]!==room.messages.length){room.read[mode]=room.messages.length;save();}
}
function sendChatMessage(value){
 if(isGuest()||window.ReelAccess.isAdmin)return false;
 const text=String(value||'').trim(),context=chatContext();
 if(!text||text.length>1000||!context||(!context.sample&&!conversationOpen(context.room)))return false;
 if(context.sample&&!state.sampleMessages)state.sampleMessages=sampleChatMessages();
 const list=context.sample?state.sampleMessages:context.messages;
 list.push({text,sender:window.ReelAccess.mode(),at:Date.now()});
 if(!context.sample&&conversationBooking(context.room))state.messages=context.messages;
 save();return true;
}
function chatTime(at){if(!Number.isFinite(at))return '';return new Intl.DateTimeFormat(signupLanguage(),{timeZone:'Asia/Seoul',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit',hour12:false}).format(at);}
function conversationCard(room){
 const b=conversationBooking(room)||room,last=room.messages.at(-1),guideMode=window.ReelAccess.mode()==='guide',unread=conversationUnread(room);
 return `<a class="conversation-item card pad" href="#${esc(conversationRoute(room))}"><span class="conversation-avatar">${icon('messages')}</span><div><div class="conversation-heading"><h2>${esc(guideMode?(b.customer||'Traveler'):room.guide)}</h2>${last?.at?`<time datetime="${new Date(last.at).toISOString()}">${esc(chatTime(last.at))}</time>`:''}</div><p>${esc(room.tripTitle)} · ${requestPeriod(room)}</p><p class="conversation-preview">${esc(last?.text||'Discuss your itinerary and meeting point.')}</p><span class="badge">${conversationStatus(room)}</span></div>${unread?`<span class="chat-unread" aria-label="${unread} unread messages">${unread}</span>`:'<span aria-hidden="true">›</span>'}</a>`;
}
function messages(){
 const rooms=syncConversations().slice().sort((a,b)=>(b.messages.at(-1)?.at||b.createdAt)-(a.messages.at(-1)?.at||a.createdAt));
 const preview=isGuest()?sampleChatMessages():(state.sampleMessages||sampleChatMessages());
 return `${title('','Chats')}${rooms.map(conversationCard).join('')}${rooms.length?'':`<section class="sample-conversation"><p class="hint">No conversations yet. Explore a sample to see how chat works.</p><a class="conversation-item card pad" href="#chat?sample=1"><span class="conversation-avatar">${icon('messages')}</span><div><h2>${window.ReelAccess.mode()==='guide'?'Jamie':'Mina'}</h2><p>A slow afternoon in Seongsu</p><p class="conversation-preview">${esc(preview.at(-1)?.text)}</p><span class="badge">Sample conversation</span></div><span aria-hidden="true">›</span></a></section>`}`;
}
function chat(){
 const context=chatContext();if(!context)return empty('Conversation not found.','Choose a conversation from your inbox.','messages','Chats');
 const b=context.booking,guideMode=window.ReelAccess.mode()==='guide',mode=window.ReelAccess.mode(),room=context.room,open=context.sample||conversationOpen(room),booked=!context.sample&&conversationBooking(room);
 const detail=context.sample?'<p class="hint">Sample conversation</p>':`<section class="chat-trip-context"><strong>${esc(room.tripTitle)}</strong><p>${requestPeriod(room)} · ${conversationStatus(room)}</p>${booked?btn('Booking details',guideMode?'guide-desk':'booking','secondary small'):room.requestId===state.request?.id?btn('View proposal',guideMode?'guide-desk':'requested','secondary small'):''}</section>`;
 return `<div class="centerbox">${title('',guideMode?'Chat with traveler':`${esc(b.guide)} — your mate`,'')}${detail}<div class="card pad"><div class="chat" id="chat-log" role="log" aria-live="polite" aria-label="Conversation"><div class="bubble">Confirm itinerary and price changes through a revised proposal.<small>Information</small></div>${context.messages.map((m,i)=>{const mine=(m.sender||'customer')===mode;return `<div class="bubble ${mine?'mine':''}">${esc(m.text)}<small>${mine?'Me':guideMode?'Traveler':esc(b.guide)}${m.at?` · <time datetime="${new Date(m.at).toISOString()}">${esc(chatTime(m.at))}</time>`:''}${!context.sample&&mine&&(room.read?.[guideMode?'customer':'guide']||0)>i?' · Read':''}</small></div>`;}).join('')}</div>${isGuest()?btn('Sign up to chat','signup'):open?`<form id="chat-form" class="chat-composer"><input name="text" aria-label="Message" maxlength="1000" required placeholder="e.g. Which station exit should we use?"><button type="submit" class="btn">Send</button></form>`:'<p class="notice">This conversation is closed. You can still view its history.</p>'}<p class="hint">Demo conversation saved only in this browser.</p></div></div>`;
}

function refundEstimate(){return 0;}

function cancel(){const b=state.booking;if(!b||!['awaiting_mate_fee','confirmed'].includes(b.status))return empty('No booking is available to cancel.','Check your current booking status.','booking','View booking');return `${title('','Cancel your booking 요청')}<form id="cancel-form" class="card pad"><p>${b.status==='awaiting_mate_fee'?'Withdraw this unconfirmed booking request.':'Confirm any cash payments with your mate. Reeltrip does not collect or automatically refund trip payments.'}</p><label>Reason<textarea name="reason" required minlength="2" maxlength="500"></textarea></label><label class="check"><input name="terms" type="checkbox" required>I confirm this cancellation request.</label><button type="submit" class="btn danger">${b.status==='awaiting_mate_fee'?'Withdraw request':'Submit cancellation request'}</button></form>`;}

function review(){if(state.booking?.status!=='completed')return empty('Reviews open after your trip.','You can leave a review once the booking is marked completed.','booking','View booking');if(state.review)return empty('Your review is already saved.','Thank you for sharing your experience.','booking','View my review');return `<div class="centerbox">${title('Share your experience','How was your trip?','')}<form id="review-form" class="card pad"><label>Overall rating</label><div class="rating">${[1,2,3,4,5].map(n=>`<button type="button" class="${state.rating>=n?'selected':''}" data-action="rate" data-value="${n}" aria-label="Out of 5: ${n} stars" aria-pressed="${state.rating===n}">★</button>`).join('')}</div><label>My review<textarea name="body" required minlength="10" maxlength="1000" placeholder="What went well? Was the tour as described? Share anything other travelers should know."></textarea></label><p id="review-error" class="error" role="alert"></p><button type="submit" class="btn" style="margin-top:20px">Save review</button></form></div>`;}
function side(role,content){if(role==='guide')return content;const list=screens.filter(s=>s.role===role);return `<div class="adminlayout"><nav class="sidenav" aria-label="Role navigation">${list.map(s=>`<a class="${current()===s.route?'active':''}" href="#${s.route}">${s.name}</a>`).join('')}</nav><section>${content}</section></div>`;}
function guideDesk(){const r=state.request;return side('guide',`${state.booking?.status==='awaiting_mate_fee'?`<section class="card pad"><span class="badge">The traveler selected you</span><h2>Pay the matching fee to confirm</h2><p>${money(state.booking.feeAmount)} · 10% of the trip price</p>${btn('Pay fee & confirm','guide-fee')}</section>`:state.booking?.feeStatus==='paid'?btn(signupText('feeReceipt'),'guide-earnings','secondary small'):''}${title('','Open trips','Review public trips and propose a route and price.')}${!r?empty('No new requests.','Keep your availability up to date.','guide-calendar','Manage availability'):`<div class="card pad"><span class="badge">${r.id} · ${statusLabel(r.status)}</span><h2 style="margin:15px 0">${requestPeriod(r)} · ${r.party} ${r.party===1?"guest":"guests"} · ${r.time}</h2><p>${r.requestType==='free'?esc(r.region)+' · 자유 견적 · '+tripLength(r.dayCount||1):r.stops.map(p=>esc(p.name)).join(' → ')}</p><div class="notice">Traveler notes: ${esc(r.notes||'No additional requests')}<br>Must-visits: ${r.must.map(id=>r.stops.find(p=>p.id===id)?.name||id).map(esc).join(', ')||'None'}</div><div class="buttons">${r.status==='requested'||r.status==='quoted'?`${btn('Review itinerary and proposal','guide-quote')}`:''}</div></div>`}<details class="trip-settings"><summary><span>Work summary</span><b>＋</b></summary><div class="metrics"><div class="metric">Awaiting reply<strong>${r?.status==='requested'?1:0}</strong></div><div class="metric">Proposals issued<strong>${state.quote?1:0}</strong></div><div class="metric">Bookings<strong>${state.booking?1:0}</strong></div></div></details>`);}
function guideQuote(){const r=state.request;if(!r||!['requested','quoted'].includes(r.status)||state.booking)return side('guide',empty('No request available to proposal.','Check its status in your inbox.','guide-desk','Requests'));return side('guide',`${title('Edit proposal','Shape the traveler’s day','The published itinerary and price appear in the traveler proposal.')}<form id="quote-form" class="card pad"><label class="developer-only">Sending account<select name="sender"><option value="mina">Mina</option><option value="jun">Jun</option></select></label>${window.ReelRevenue.calculator(state.request.party)}<label>Final itinerary (shown to the traveler)<textarea name="plan" required minlength="10" maxlength="2000" placeholder="Enter the places and mate hours for each day.">${esc(state.quote?.plan||(r.requestType==='free'?'':requestPlan(r)))}</textarea></label><label style="margin-top:18px">Changes and reasons (shown to the traveler)<textarea name="reason" required minlength="5" maxlength="500">${esc(state.quote?.reason||'The selected places are unchanged. Travel and rest times need final confirmation.')}</textarea></label><div class="formrow"><label>Total trip price (KRW)<input type="number" name="amount" min="100000" max="14000000" step="500" readonly required value="${state.quote?.amount||window.ReelRevenue.quoteAmount(state.request.party)}"></label><label>Proposal validity<input value="24 hours after issue · Proposed policy" disabled></label></div><div class="notice">포함: English mate for the selected duration and itinerary preparation / 불포함: 식비·Shopping·교통·입장료. Updating your proposal keeps other mates’ proposals unchanged.</div><p id="quote-error" class="error" role="alert"></p><button class="btn" type="submit">Send a trip proposal</button></form>`);}
function guideCalendar(){return side('guide',`${title('Availability','Manage availability','')}<div class="card pad"><h2>${state.request?.date||state.date}</h2><p class="muted" style="margin:15px 0">Accepting new requests: <strong>${state.available?'Available':'Unavailable'}</strong></p>${action(state.available?'Mark this date unavailable':'Mark this date available','availability','secondary')}<div class="notice">This setting does not cancel confirmed bookings. Contact operations if a change is needed.</div></div>`);}
function earnings(){const b=state.booking;return side('guide',`${title('','Matching fee','Collect the trip price directly from the traveler in cash.')}<section class="card pad"><div class="summaryrow"><span>Agreed cash amount</span><b>${money(b?.amount||0)}</b></div><div class="summaryrow"><span>10% matching fee</span><b>${money(b?.feeAmount||0)}</b></div><div class="summaryrow"><span>Matching fee payment status</span><b>${!b?'No booking':b.feeStatus==='paid'?'Paid':b.feeStatus==='failed'?'Payment failed':'Pending payment'}</b></div><p>The platform does not settle or transfer trip payments. Confirm cash receipt directly with the traveler.</p>${b?.status==='awaiting_mate_fee'?btn('Pay fee & confirm','guide-fee'):''}</section>`);}

function admin(){return side('admin',`${title('Operations','Operations overview','These figures reflect local browser data, not real business activity.')}<div class="metrics"><div class="metric">Saved places<strong>${state.board.length}</strong></div><div class="metric">Needs checking<strong>${state.places.filter(p=>!p.verified).length}</strong></div><div class="metric">${guided?'Bookings':'Support'}<strong>${guided?(state.booking?1:0):state.tickets.length}</strong></div></div><div class="card pad"><h2>Needs your attention</h2><ul class="listclean"><li><a href="#admin-places">Review places and locations →</a></li><li><a href="#admin-support">Support tickets: ${state.tickets.filter(t=>t.status==='open').length} →</a></li>${guided?`<li><a href="#admin-guides">Jun’s mate application: ${statusLabel(state.adminReview)} →</a></li><li><a href="#admin-bookings">Check bookings and refunds →</a></li>`:''}</ul></div>`);}
function adminPlaces(){return side('admin',`${title('Place quality','Review places','Review original place data and correction history.')}<div class="tablewrap"><table><thead><tr><th>Place</th><th>Status</th><th>Review action</th></tr></thead><tbody>${state.places.map(p=>`<tr><td><b>${esc(p.name)}</b><br>${esc(p.address)}</td><td><span class="badge ${p.verified?'':'warm'}">${p.verified?'Successful':p.rejected?'Rejected':'Needs checking'}</span></td><td><button class="textbtn" data-action="correct" data-id="${p.id}">Review and edit</button>${!p.verified?`<br><button class="textbtn" data-action="reject-place" data-id="${p.id}">Rejected</button>`:''}</td></tr>`).join('')}</tbody></table></div>`);}
function adminSupport(){return side('admin',`${title('Support tickets:','Support and data requests','Requests and status updates stay in this browser. Nothing is sent externally.')}<div class="stack">${state.tickets.length?state.tickets.map(t=>`<div class="card pad"><span class="badge">${t.id} · ${statusLabel(t.status)}</span><h3 style="margin:13px 0">${esc(t.type)}</h3><p>${esc(t.body)}</p>${t.status==='open'?`<button class="btn secondary small" style="margin-top:15px" data-action="resolve-ticket" data-id="${t.id}">Mark resolved</button>`:''}</div>`).join(''):empty('No support requests yet.','Create a local request from the help screen.','support','Open support')}</div>`);}
function adminGuides(){return side('admin',`${title('Mate verification','Review mate credentials','Fictional applicant Jun · No real credentials or identity documents are collected.')}<form id="verify-form" class="card pad"><div class="guide"><div class="portrait">Jun</div><div><h2>Jun · Anguk</h2><span class="badge">${statusLabel(state.adminReview)}</span></div></div><div class="notice">In a live service, staff must verify credentials, identity and contracts. Sensitive evidence must not appear on public profiles.</div>${['Check tourist interpreter qualification and language','Check that the identity matches the evidence','Check mate contract and payout agreement'].map((t,i)=>`<label class="check"><input name="v${i}" type="checkbox" required>${t} (review only)</label>`).join('')}<div class="buttons"><button type="submit" class="btn">Approve and publish profile</button>${action('Request information and hide profile','guide-needs-info','secondary')}</div></form>`);}
function adminBookings(){const b=state.booking;return side('admin',`${title('','Matching & booking management')}${!b?'<p>No bookings.</p>':`<section class="card pad"><h2>${esc(b.guide)} · ${esc(b.date)}</h2><span class="badge">${statusLabel(b.status)}</span><div class="summaryrow"><span>Agreed cash amount</span><b>${money(b.amount)}</b></div><div class="summaryrow"><span>10% matching fee</span><b>${money(b.feeAmount)}</b></div><p>Matching fee status: ${esc(b.feeStatus)}</p><p>Cancellation reason: ${esc(b.cancelReason||'—')}</p><p>Trip payments are direct cash transactions. Matching fee refunds require separate review.</p>${b.status==='cancellation_requested'?action('Confirm cancellation','confirm-cash-cancel','secondary'):''}</section>`}`);}

const demoSignupCode='482916';
let signupEmailStep='address';

const signupLocales = ['ko', 'en', 'zh-CN', 'ja'];
const appLanguage = document.documentElement.lang;
const preferenceKey='reeltrip-interface-language';
const explicitLanguage=new URLSearchParams(location.search).get('lang');
let preferredLanguage=appLanguage;
try {
 const saved=localStorage.getItem(preferenceKey);
 if(signupLocales.includes(saved))preferredLanguage=saved;
 if(signupLocales.includes(explicitLanguage))localStorage.setItem(preferenceKey,explicitLanguage);
} catch {}
function signupLanguage(){
 return signupLocales.includes(explicitLanguage)?explicitLanguage:preferredLanguage;
}
function interfaceMarkup(html){
 if(!['zh-CN','ja'].includes(signupLanguage()) || ['signup','signup-email'].includes(current()))return html;
 const personal=new Set([state.profile?.nickname, ...state.places.filter(p=>p.manual&&!p.recommended).map(p=>p.name)]);
 return window.ReelInterfaceCopy?.markup(html,signupLanguage(),personal)??html;
}
function signupText(key){
 return window.ReelSignupCopy[key][signupLocales.indexOf(signupLanguage())];
}
function signupLanguageLink(asMenuRow=false){
 const names = ['한국어', 'English', '简体中文', '日本語'];
 const pages = ['index.html?lang=ko', 'english.html?lang=en', 'index.html?lang=zh-CN', 'index.html?lang=ja'];
 const links = signupLocales.map((lang, i) => '<a lang="'+lang+'" href="'+pages[i]+'#'+current()+'"'+(lang===signupLanguage()?' aria-current="true"':'')+'>'+names[i]+(lang===signupLanguage()?' ✓':'')+'</a>').join('');
 if(asMenuRow){
  const activeName=names[signupLocales.indexOf(signupLanguage())];
  return '<details class="signup-locale"><summary class="guest-account-row">'+icon('settings')+'<span>'+signupText('languageSetting')+'</span><span class="value">'+activeName+'</span><span class="arrow" aria-hidden="true">›</span></summary><div>'+links+'</div></details>';
 }
 return '<details class="signup-locale"><summary class="signup-language" aria-label="'+signupText('language')+'">'+signupText('languageSetting')+' · '+names[signupLocales.indexOf(signupLanguage())]+' ▾</summary><div>'+links+'</div></details>';
}

const memberSessionKey = 'reeltrip-signup-preview-member';
let previewMember = false;
try { previewMember = sessionStorage.getItem(memberSessionKey) === 'yes'; } catch {}
function isGuest(){ return !window.ReelAccess.isAdmin && !previewMember; }
const sharedNicknameKey='reeltrip-preview-nickname-v1';
function ensureMemberNickname(){
 let directory={};
 let shared='';
 try{
  shared=localStorage.getItem(sharedNicknameKey)||'';
  directory=readNicknameDirectory();
 }catch{}
 let nickname=shared || state.profile?.nickname;
 if(!nickname){
  const bases=window.ReelNicknameBases[signupLanguage()];
  const count=bases.length*10000;
  const start=Math.floor(Math.random()*count);
  for(let offset=0;offset<count;offset++){
   const slot=(start+offset)%count;
   const candidate=bases[Math.floor(slot/10000)]+' '+String(slot%10000).padStart(4,'0');
   if(!nicknameProblem(candidate,directory)){nickname=candidate;break;}
  }
 }
 if(!nickname)return;
 state.profile={...state.profile,nickname};
 if(shared===nickname)return;
 try{
  directory[normalizeNickname(nickname)]=nicknameOwner;
  localStorage.setItem(nicknameDirectoryKey,JSON.stringify(directory));
  localStorage.setItem(sharedNicknameKey,nickname);
 }catch{}
}
if(previewMember && !window.ReelAccess.isAdmin)ensureMemberNickname();
function setPreviewMember(value){
 previewMember=value;
 if(value)ensureMemberNickname();
 try { if(value) sessionStorage.setItem(memberSessionKey,'yes'); else sessionStorage.removeItem(memberSessionKey); } catch {}
}
