const views={signup,'signup-email':signupEmail,'guide-fee':guideFee,settings:settingsPage,notifications,home,processing,results,manual,board,planner,share,trips,account,support,policies,guides,guide:guidePage,request,requested,quote,checkout,booking,messages,chat,cancel,review,'guide-desk':guideDesk,'guide-quote':guideQuote,'guide-calendar':guideCalendar,'guide-earnings':earnings,admin,'admin-places':adminPlaces,'admin-support':adminSupport,'admin-guides':adminGuides,'admin-bookings':adminBookings};
function render(){
 markChatRead();
 if(!['member-required','signup','signup-email'].includes(current())){pendingRestaurant=null;pendingEstimate=false;}
 const route=current();
 if(isGuest() && route!=='signup' && route!=='signup-email'){
  clearTimeout(timer);
  document.body.dataset.route=route;
  document.documentElement.lang=signupLanguage();
  const skip=$('.skip');if(skip)skip.textContent=signupText('skip');
  const publicViews={home,messages,chat,board:guestBoard,trips:guestTrips,account:guestAccount,results:guestPlaces,guides:guestGuides,guide:guidePage,policies};
  if(route==='request')pendingRequestRoute=location.hash.slice(1);
  const canBrowse=Object.hasOwn(publicViews,route);
  if(canBrowse)lastBrowseRoute=route;
  const content=canBrowse?publicViews[route]():guestGate();
  $('#app').innerHTML=interfaceMarkup(layout(content));
  if(route==='home')loadRecommendations();
  document.title=canBrowse?(window.ReelInterfaceCopy?.text(byRoute(route)?.name||'Reeltrip',signupLanguage())||byRoute(route)?.name):signupText('needMember');
  return;
 }
 if(['requested','quote','checkout','booking','chat','cancel','review'].includes(current()))guidesTab='requests';if(fillExampleCoordinates())save();clearTimeout(timer);const r=current();document.body.dataset.route=r;const signingUp=r==='signup'||r==='signup-email';document.documentElement.lang=signupLanguage();const skipLink=$('.skip');if(skipLink)skipLink.textContent=signupText('skip');$('#app').innerHTML=interfaceMarkup(layout(byRoute(r)?(window.ReelAccess.allowed(byRoute(r).role,r)?(views[r]()+providerCredits()):window.ReelAccess.blocked()):empty('화면을 찾을 수 없어요.','메뉴에서 다시 이동해 주세요.')));document.title=signingUp?signupText(r==='signup'?'title':'emailTitle'):`${byRoute(r)?.name||'Reeltrip'}`;document.title=window.ReelInterfaceCopy?.text(document.title,signupLanguage())||document.title;mountMaps();window.ReelRevenue.mount();if(r==='processing'&&state.extraction!=='failed'){timer=setTimeout(()=>{state.extraction='partial';save();go('results');},1400);}if(r==='chat')$('#chat-log')?.scrollTo(0,99999);}
function modal(html,kind=''){html=interfaceMarkup(html);const d=$('#dialog');d.dataset.kind=kind;d.innerHTML=html;if(!d.open)d.showModal();}
function snapshot(){return state.board.map(place).filter(Boolean).map(p=>({...p}));}
function makeQuote(amount,plan,reason,pricing,sender='mina'){const r=state.request;if(!r||!['requested','quoted'].includes(r.status)||state.booking)return false;if(!state.available){toast('Your mate is unavailable on this date. Choose another date.');return false;}if(amount===undefined)amount=240000*(r.dayCount||1);const existing=proposals().find(q=>q.guideId===sender);state.quote={guideId:sender,pricingPolicyVersion:"2026-11-17-v1",feeRate:.1,feeVatIncluded:null,pricing:JSON.parse(JSON.stringify(pricing||{rate:60000,hours:4*(r.dayCount||1),extra:10000})),id:'QT-'+r.id+'-'+sender,version:(existing?.version||0)+1,guide:sender==='jun'?'Jun':'Mina',requestType:r.requestType||'itinerary',tripTitle:r.tripTitle,region:r.region,endDate:r.endDate||r.date,dayCount:r.dayCount||1,days:JSON.parse(JSON.stringify(r.days||[])),date:r.date,time:r.time,party:r.party,amount,plan:plan||requestPlan(r),reason:reason||'Your selected stops and visit order are unchanged. The mate still needs to confirm travel time, breaks and whether each visit is possible.',expires:Date.now()+86400000};state.proposals=[...proposals().filter(q=>q.guideId!==sender),state.quote];state.request.status='quoted';save();return true;}
