function sample(){state.source='Coffee and walks in Seongsu';state.filter='All';state.selected=['forest','cafe','shop'];state.extraction='processing';save();go('processing');}
function loadScenario(kind){
 state=initial();state.board=['forest','cafe','shop'];state.saved=true;
 if(guided&&kind!=='plan'){
  state.request={id:'RQ-DEMO-SAMPLE',status:'requested',date:state.date,time:state.time,party:2,notes:'We would like a relaxed pace with time for photos.',guide:'Mina',guideId:'mina',stops:snapshot(),must:[],createdAt:Date.now()};
  if(kind!=='request')makeQuote();
  if(['booking','cancel','completed'].includes(kind)){state.request.status='booked';state.booking={...JSON.parse(JSON.stringify(state.quote)),id:'RT-DEMO-SAMPLE',quoteVersion:state.quote.version,status:kind==='completed'?'completed':kind==='cancel'?'cancellation_requested':'confirmed',customer:'Jamie',email:'jamie@example.com',requestedAt:Date.now(),confirmedAt:Date.now(),feePaidAt:Date.now(),feeAmount:Math.round(state.quote.amount*.1),feeRate:.1,feeStatus:'paid',paymentMethod:'cash',cashStatus:'uncollected',policyVersion:'CASH-MATCH-10-V1',refundStatus:kind==='cancel'?'Under review':'None'};
   if(kind==='cancel'){state.booking.estimatedRefund=refundEstimate();state.booking.cancelReason='Travel plans changed';state.booking.cancelledAt=Date.now();}
  }
 }
 save();$('#dialog').close();go(({plan:'planner',request:'requested',quote:'quote',booking:'booking',cancel:'admin-bookings',completed:'review'})[kind]||'planner');toast('State loaded. No real requests or transactions take place.');
}
document.addEventListener('error',e=>{if(e.target.matches?.('.provider-photo img')){e.target.parentElement.innerHTML=art();}},true);
document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelectorAll('.place-menu[open]').forEach(menu=>{menu.open=false;menu.querySelector('summary').focus();});}});
document.addEventListener('click',e=>{document.querySelectorAll('.place-menu[open]').forEach(menu=>{if(!menu.contains(e.target)||e.target.closest('[data-action]'))menu.open=false;});if(e.target.closest('.skip')){e.preventDefault();$('#main')?.focus();return;}const b=e.target.closest('[data-action]');if(!b)return;e.preventDefault();const a=b.dataset.action,id=b.dataset.id;
 if(a==='save-recommendation'){saveRecommendation(recommendationRows[Number(id)]);return;}
 if(a==='recommendation-retry'){loadRecommendations(recommendationQuery,true);return;}
 if(a==='discover-query'){startDiscovery(b.dataset.query);return;}
 if(a==='browse-guest'){setPreviewMember(false);go('home');return;}
 if(isGuest() && !['signup-provider','signup-edit-email','guides-tab','close'].includes(a)){
  if(a==='sample'){go('results');return;}
  pendingRestaurant=a==='save-restaurant'?id:null;pendingEstimate=a==='guest-trip-estimate';
  go('member-required');return;
 }
 if(a==='preview-example-pin'){previewAPIPlace(pickerPlaces().findIndex(p=>p.id===id));return;}
 if(a==='place-picker-tab'){placePickerTab=id==='saved'?'saved':'search';placeSelectionVersion++;pendingAPIPlace=null;placePickerSelected='';render();return;}
 if(a==='preview-api-place'){previewAPIPlace(Number(id),b);return;}
 if(a==='save-api-place'){saveAPIPlace();return;}
 if(a==='resolve-place'){resolvePlace(id,addingToTrip());return;}
 if(a==='save-restaurant'){saveRestaurant(id);return;}
 if(a==='open-proposal-chat'){const q=proposals().find(q=>q.id===id);if(!q||!state.request?.id)return;const room=ensureConversation(q);save();go(conversationRoute(room));return;}
 if(a==='confirm-cash-cancel'){if(window.ReelAccess.isAdmin&&state.booking?.status==='cancellation_requested'){state.booking.status='cancelled';save();render();}return;}
 if(a==='check-nickname'){checkNickname();return;}
 if(a==='signup-provider'){
  setPreviewMember(true);
  if(!resumeSignupAction())go(window.ReelAccess.home());
  return;
 }
 if(a==='signup-edit-email'){showSignupEmailStep('address');return;}
 if(a==='edit-profile'){editProfile();return;}
 if(a==='remove-profile-photo'){profileDraftPhoto='';$('#profile-photo').value='';$('#profile-photo-preview').innerHTML=profileAvatar('');$('#profile-photo-clear').hidden=true;$('#profile-camera-button').hidden=false;return;}
 if(a==='my-proposals'){guidesTab='requests';go('guides');return;}
 if(a==='select-proposal'){const q=proposals().find(q=>q.id===id);if(q){state.viewedProposals=[...new Set([...(state.viewedProposals||[]),q.id+':'+q.version])];state.quote=q;save();go('quote');}return;}
 if(a==='demo-proposals'){const demoPlan=state.request?.requestType==='free'?state.request.days.map((d,i)=>`Day ${i+1} · ${d.date} · ${state.request.region}\nSample route: Neighborhood walk, cafe, and shops`).join('\n'):undefined;makeQuote(240000*(state.request?.dayCount||1),demoPlan,'A cafe and walking route tailored to your trip length.',undefined,'mina');makeQuote(210000*(state.request?.dayCount||1),demoPlan,'A route through local shops with less walking.',undefined,'jun');render();return;}
 if(a==='guides-tab'){if(['discover','requests'].includes(id)){guidesTab=id;render();}return;}
 if(a==='notification-filter'){if(['all','trip','guide'].includes(id)){notificationFilter=id;render();}return;}
 if(a==='notifications-read-all'){markNotificationsRead(notificationItems().map(n=>n.id));render();return;}
 if(a==='notification-open'){const item=notificationItems().find(n=>n.id===id);if(item){markNotificationsRead([id]);go(item.route);}return;}

 if(a==='trip-add-menu'){tripAddMenu();return;}
 if(a==='trip-pick-places'){tripPlacePicker();return;}
 if(a==='trip-add-place'){if(window.REEL_MAPS_CONFIG?.apiKey&&!pinEligible(place(id))){resolvePlace(id,true);return;}if(addTripPlace(id)){render();tripPlacePicker();}else toast('Day에 20 places까지 담을 수 있어요.');return;}
 if(a==='trip-manual'){$('#dialog').close();go('manual?from=trips');return;}
 if(a==='edit-trip'){editTripInfo();return;}
 if(a==='add-note'){editTripNote();return;}
 if(a==='edit-note'){editTripNote(Number(id));return;}
 if(a==='trip-date'){chooseTripDate(b.dataset.value);renderTripCalendar();$('#dialog').querySelector(`[data-value="${b.dataset.value}"]`)?.focus({preventScroll:true});return;}
 if(a==='trip-more-months'){tripDraft.months+=12;renderTripCalendar();return;}
 if(a==='trip-dates-next'){tripDetailsDialog();return;}
 if(a==='trip-dates-back'){const f=$('#new-trip-form');tripDraft.title=f.elements.title.value;tripDraft.party=f.elements.party.value;renderTripCalendar();return;}
 if(a==='new-trip'){newTripDialog();return;}
 if(a==='open-trip'){if(selectTrip(id))go(tripDetailRoute());return;}
 if(a==='library-to-trip'){if(window.REEL_MAPS_CONFIG?.apiKey&&!pinEligible(place(id))){resolvePlace(id,true);return;}if(state.board.includes(id)){go('planner');return;}libraryIds();if(!state.board.includes(id)){if(state.board.length>=20){toast('Day에 20 places까지 담을 수 있어요.');return;}state.board.push(id);state.saved=false;save();render();}toast('Added to the selected day.');return;}
 if(a==='overview-day'){switchDay(Number(b.dataset.value));go('planner');}
 else if(a==='day'){switchDay(Number(b.dataset.value));}
 else if(a==='add-day'){ensureDays();if(state.days.length>=7)return;stashDay();const date=new Date(state.days[state.days.length-1].date+'T12:00:00Z');date.setUTCDate(date.getUTCDate()+1);state.days.push({date:date.toISOString().slice(0,10),time:'10:00',ids:[],durations:{}});switchDay(state.days.length-1);}
 else if(a==='focus-place'){if(window.REEL_MAPS_CONFIG?.apiKey&&!pinEligible(place(id))){resolvePlace(id,true);return;}state.focus=id;save();render();}
 else if(a==='move-day'){ensureDays();modal(`<h2>Which day works best?</h2><p>Move this stop to the end of another day.</p><div class="stack">${state.days.map((d,i)=>i===state.day?'':action(`Day ${i+1} · ${d.date}`,'transfer-day','secondary',`data-id="${id}" data-value="${i}"`)).join('')||'<p>Add another day first.</p>'}</div>${action('Close','close','secondary')}`);}
 else if(a==='transfer-day'){const target=state.days[Number(b.dataset.value)];if(target.ids.length>=20&&!target.ids.includes(id)){toast('You can add up to 20 places per day.');return;}if(!target.ids.includes(id)){target.ids.push(id);target.durations[id]=place(id).duration;}state.board=state.board.filter(x=>x!==id);state.saved=false;save();$('#dialog').close();render();toast('Place moved to another day.');}
 else if(a==='scenarios')modal(`<h2>Choose a review state</h2><p>This replaces the local data for this option. No real requests, payments or notifications are sent.</p><div class="stack">${action('Ready to edit itinerary','load-scenario','secondary','data-kind="plan"')}${guided?`${action('Awaiting mate reply','load-scenario','secondary','data-kind="request"')}${action('Proposal received · Before payment','load-scenario','secondary','data-kind="quote"')}${action('Confirmed','load-scenario','secondary','data-kind="booking"')}${action('Cancellation requested · Refund review','load-scenario','secondary','data-kind="cancel"')}${action('Trip complete · Write a review','load-scenario','secondary','data-kind="completed"')}`:''}</div><div class="buttons">${action('Go back','close','secondary')}</div>`);
 else if(a==='load-scenario')loadScenario(b.dataset.kind);
 else if(a==='home-category'){state.source='Coffee and walks in Seongsu';state.filter=b.dataset.value;save();go('results');}
 else if(a==='sample')sample();
 else if(a==='sample-results'){state.source='Coffee and walks in Seongsu';state.filter='All';save();go('results');}
 else if(a==='extract-fail'){clearTimeout(timer);state.extraction='failed';save();render();}
 else if(a==='filter'){state.filter=b.dataset.value;save();render();}
 else if(a==='save-places'){const unresolved=state.selected.find(id=>!pinEligible(place(id)));if(window.REEL_MAPS_CONFIG?.apiKey&&unresolved){resolvePlace(unresolved);return;}state.library=[...new Set([...libraryIds(),...state.selected])];save();go('board');toast('Selected places saved.');}
 else if(a==='add-board'){const unresolved=state.selected.find(id=>!pinEligible(place(id)));if(window.REEL_MAPS_CONFIG?.apiKey&&unresolved){resolvePlace(unresolved,true);return;}if(state.selected.some(id=>!place(id)?.verified)){toast('Check the address of any unverified place first, so you do not visit the wrong branch.');return;}const ids=[...new Set([...state.board,...state.selected])];if(ids.length>20){toast('Day에 20 places까지 담을 수 있어요.');return;}state.library=[...new Set([...libraryIds(),...state.selected])];state.board=ids;state.saved=false;save();go('planner');}
 else if(a==='correct'){resolvePlace(id,isTripDetail()||current()==='planner');}
 else if(a==='close')$('#dialog').close();
 else if(a==='must'){state.must=state.must.includes(id)?state.must.filter(x=>x!==id):[...state.must,id];save();render();}
 else if(a==='remove'&&current()==='board'){state.library=libraryIds().filter(x=>x!==id);save();render();}
 else if(a==='remove'){state.board=state.board.filter(x=>x!==id);state.must=state.must.filter(x=>x!==id);state.saved=false;save();render();}
 else if(a==='move'){const i=state.board.indexOf(id),j=i+Number(b.dataset.dir);if(j>=0&&j<state.board.length){[state.board[i],state.board[j]]=[state.board[j],state.board[i]];state.saved=false;save();render();}}
 else if(a==='save-trip'){state.saved=true;save();render();toast('All days of your trip have been saved in this browser.');}
 else if(a==='copy'){const text=tripText();if(navigator.clipboard?.writeText)navigator.clipboard.writeText(text).then(()=>toast('Itinerary copied.')).catch(()=>{$('#share-text').select();toast('Select the itinerary text and copy it.');});else{$('#share-text').select();toast('Select the itinerary text and copy it.');}}
 else if(a==='download-trip'){download('reeltrip-itinerary.json',{title:state.title,date:state.date,time:state.time,timezone:'Asia/Seoul',stops:snapshot().map(({name,address,duration})=>({name,address,duration})),day:state.day+1,demo:true});toast('Itinerary downloaded.');}
 else if(a==='print')window.print();
 else if(a==='export-data'){download(`reeltrip-data.json`,state);toast('Saved data exported.');}
 else if(a==='reset')modal(`<h2>Delete saved data?</h2><p>Reeltrip의 Saved places,  days정과 체험 기록을 Remove합니다. </p><div class="buttons">${action('Delete saved data','confirm-reset','danger')}${action('Keep data','close','secondary')}</div>`);
 else if(a==='confirm-reset'){try{localStorage.removeItem(key);localStorage.removeItem(sharedNicknameKey);}catch{}state=initial();$('#dialog').close();go('home');toast('앱의 Save 정보를 Remove했습니다.');}
 else if(a==='guide-filter'){state.guideFilter=b.dataset.value;save();render();}
 else if(a==='choose-guide'){state.guide=id;save();go('guide');}
 else if(a==='demo-quote'){if(makeQuote()){go('quote');toast('Your proposal is ready.');}}
 else if(a==='withdraw'){if(state.request?.status==='requested'){state.request.status='withdrawn';save();render();}}
 else if(a==='renew-quote'){if(makeQuote(state.quote?.amount||240000,state.quote?.plan,state.quote?.reason,state.quote?.pricing,state.quote?.guideId||'mina'))render();else toast('This request cannot be renewed.');}
 else if(a==='expire-quote'){if(state.quote){state.quote.expires=Date.now()-1;save();render();}}
 else if(a==='complete-trip'){if(state.booking?.status==='confirmed'){state.booking.status='completed';save();render();toast('Trip marked completed locally.');}}
 else if(a==='rate'){state.rating=Number(b.dataset.value);save();document.querySelectorAll('.rating button').forEach(x=>{x.classList.toggle('selected',Number(x.dataset.value)<=state.rating);x.setAttribute('aria-pressed',String(Number(x.dataset.value)===state.rating));});}
 else if(a==='decline'){if(state.request&&['requested','quoted'].includes(state.request.status)&&!state.booking)modal(`<h2>Decline request</h2><form id="decline-form"><label>Reason<textarea name="reason" required minlength="5" maxlength="500"></textarea></label><div class="buttons"><button class="btn danger" type="submit">Decline request</button>${action('Go back','close','secondary')}</div></form>`);}
 else if(a==='availability'){state.available=!state.available;save();render();}
 else if(a==='reject-place'){const p=place(id);p.rejected=true;p.verified=false;p.reviewReason='Review: insufficient evidence for this location';save();render();}
 else if(a==='resolve-ticket'){const t=state.tickets.find(x=>x.id===id);if(t){t.status='resolved';save();render();}}
 else if(a==='guide-needs-info'){state.guideApproved=false;state.adminReview='needs_info';if(state.guide==='jun')state.guide='mina';save();render();}
 else if(a==='refund-fail')toast('Simulated payment provider error: refund review and payout hold remain in place.');
});
document.addEventListener('input',e=>{if(e.target.id==='profile-nickname'){checkedNickname='';$('#nickname-status').textContent='';$('#profile-error').textContent='';}});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='profile-photo'){const file=t.files?.[0];if(!file)return;const error=$('#profile-error');if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>1048576){error.textContent='Choose a JPG, PNG or WebP photo up to 1MB.';t.value='';return;}error.textContent='';const reader=new FileReader();$('#profile-save').disabled=true;reader.onload=()=>{profileDraftPhoto=reader.result;$('#profile-photo-preview').innerHTML=profileAvatar(profileDraftPhoto);$('#profile-photo-clear').hidden=false;$('#profile-camera-button').hidden=true;$('#profile-save').disabled=false;};reader.onerror=()=>{error.textContent='Could not load this photo. Please try again.';$('#profile-save').disabled=false;};reader.readAsDataURL(file);return;}if(t.id==='screen-jump')go(t.value);else if(t.dataset.select){const id=t.dataset.select;state.selected=t.checked?[...new Set([...state.selected,id])]:state.selected.filter(x=>x!==id);save();render();}else if(t.dataset.duration){place(t.dataset.duration).duration=Number(t.value);state.saved=false;save();render();}else if(['trip-title','trip-date','trip-time'].includes(t.id)){if(!t.value)return;state[t.id==='trip-title'?'title':t.id==='trip-date'?'date':'time']=t.value;state.saved=false;save();if(t.id==='trip-time')render();}});
document.addEventListener('submit',e=>{const f=e.target;if(!(f instanceof HTMLFormElement))return;e.preventDefault();if(f.id==='discover-search-form'){startDiscovery(f.elements.query.value);return;}if(isGuest() && !['signup-code-form','signup-email-form'].includes(f.id)){go('member-required');return;}
 const d=Object.fromEntries(new FormData(f));
 if(f.id==='place-search-form'){searchPlaces(f,d);return;}
 if(f.id==='signup-email-form'){showSignupEmailStep('code');return;}
 if(f.id==='signup-code-form'){
  if(d.code===demoSignupCode){setPreviewMember(true);if(!resumeSignupAction())showSignupEmailStep('complete');return;}
  f.elements.code.setAttribute('aria-invalid','true');
  $('#signup-code-error').textContent=signupText('wrong');
  f.elements.code.focus();
  return;
 }
 if(f.id==='profile-form'){const nickname=(d.nickname||'').normalize('NFKC').trim(),canonical=normalizeNickname(nickname);try{const directory=readNicknameDirectory(),problem=nicknameProblem(nickname,directory);if(problem){$('#profile-error').textContent=problem;checkedNickname='';return;}if(canonical!==normalizeNickname(state.profile?.nickname)&&checkedNickname!==canonical){$('#profile-error').textContent='Check nickname availability first.';return;}const updated=Object.fromEntries(Object.entries(directory).filter(([name,owner])=>owner!==nicknameOwner));updated[canonical]=nicknameOwner;localStorage.setItem(nicknameDirectoryKey,JSON.stringify(updated));localStorage.setItem(sharedNicknameKey,nickname);state.profile={nickname,photo:profileDraftPhoto};save();$('#dialog').close();render();toast('Profile saved.');}catch{$('#profile-error').textContent='Could not check availability. Please try again.';}}
 else if(f.id==='extract-form'){let url;try{url=new URL($('#video-url').value.trim());}catch{}const ok=url&&url.protocol==='https:'&&((['youtube.com','www.youtube.com','m.youtube.com'].includes(url.hostname)&&/^\/shorts\/[A-Za-z0-9_-]+\/?$/.test(url.pathname))||(['instagram.com','www.instagram.com'].includes(url.hostname)&&/^\/reels?\/[A-Za-z0-9_-]+\/?$/.test(url.pathname)));if(!ok){$('#url-error').textContent='Enter an HTTPS link to a public YouTube Short or Instagram Reel.';return;}state.source=url.href;state.extraction='processing';state.filter='All';save();go('processing');}

 else if(f.id==='suggest-place-form'){
  const name=d.name.trim(),address=d.address.trim();
  if(!name||!address){toast('Enter the place name and address.');return;}
  state.tickets.push({id:'TK-'+Date.now(),type:'Suggest a place',body:name+' · '+address,status:'open'});
  save();render();toast('Suggestion saved.');
 }
 else if(f.id==='edit-trip-form'){if(!updateTripInfo(d)){$('#edit-trip-error').textContent='Check the trip name and dates.';return;}$('#dialog').close();render();}
 else if(f.id==='trip-note-form'){if(!saveTripNote(d.note,Number(f.dataset.index))){$('#note-error').textContent='Enter a note before saving.';return;}$('#dialog').close();render();}
 else if(f.id==='new-trip-form'){const dayCount=tripRangeDays(tripDraft?.start,tripDraft?.end);if(!dayCount||tripDraft.start<tripToday()||!createTrip({...d,date:tripDraft.start,dayCount})){$('#new-trip-error').textContent='Check the trip name and dates.';return;}$('#dialog').close();go(tripDetailRoute());}
 else if(f.id==='support-form'){state.tickets.push({id:'TK-'+Date.now().toString().slice(-6),type:d.type,body:d.body.trim(),status:'open'});save();render();toast('Message saved in this browser. It was not sent externally.');}
 else if(f.id==='request-form'){const params=new URLSearchParams(location.hash.split('?')[1]||'');const result=submitTravelRequest(d,{free:params.get('mode')==='free',example:params.get('sample')==='1'});if(result.error){$('#request-error').textContent=result.error;return;}go(result.route);}
 else if(f.id==='quote-form'){if(!state.available){$('#quote-error').textContent='This date is unavailable. Update availability first.';return;}if(makeQuote(window.ReelRevenue.calculate(Number(d.hourlyRate),Number(d.guideHours),Number(d.extraGuestRate),state.request.party).total,d.plan.trim(),d.reason.trim(),{rate:Number(d.hourlyRate),hours:Number(d.guideHours),extra:Number(d.extraGuestRate)},d.sender||'mina')){go('guide-desk');toast('A new proposal version has been issued.');}}
 else if(f.id==='checkout-form'){if(!d.terms||!d.pendingAck)return;if(requestBooking(d.name.trim(),d.email)){go('booking');}else{go(state.booking?'booking':'quote');}}
 else if(f.id==='mate-fee-form'){if(!d.terms)return;if(confirmMateFee(d.outcome||'success')){go('guide-earnings');toast('The booking is confirmed after matching fee payment.');}else{const error=$('#mate-fee-error');if(error)error.textContent='Payment was not completed. The booking is still unconfirmed.';}}
 else if(f.id==='chat-form'){if(sendChatMessage(d.text)){render();$('#chat-form input')?.focus();}}
 else if(f.id==='cancel-form'){const b=state.booking;if(!b||!['awaiting_mate_fee','confirmed'].includes(b.status)||!d.terms)return;const pending=b.status==='awaiting_mate_fee';b.cancelReason=d.reason;b.status=pending?'cancelled':'cancellation_requested';if(pending){b.feeStatus='void';state.request.status='withdrawn';}save();go('booking');}
 else if(f.id==='review-form'){if(!state.rating){$('#review-error').textContent='Choose a star rating first.';return;}if(state.booking?.status!=='completed'||state.review)return;state.review={rating:state.rating,body:d.body.trim(),at:Date.now()};save();go('booking');}
 else if(f.id==='decline-form'){state.request.status='declined';state.request.reason=d.reason.trim();state.quote=null;save();$('#dialog').close();render();}
 else if(f.id==='verify-form'){state.guideApproved=true;state.adminReview='approved';save();render();toast('Jun’s fictional profile is now published.');}

});
