 if(current()==='booking'){state.request.status='booked';state.booking={...JSON.parse(JSON.stringify(state.quote)),id:'RT-COMPARE',quoteVersion:state.quote.version,status:'confirmed',customer:'Jamie',email:'jamie@example.com',policyVersion:'DRAFT-2026-11-16',refundStatus:'None'};}
